insert into hygieia.skincare_product_types (id, slug, name_el, name_en, description_el, description_en, category, key_ingredients, avoid_with, regions, audiences, skin_types, concerns, time, price_band_eur, notes_el, notes_en) values
  ('f88482f8-90fe-a95c-2ccf-8f39c059c1cf'::uuid, 'base-coat-ridge-filler', 'Βάση νυχιών που γεμίζει τις ραβδώσεις', 'Ridge-filling base coat', 'Γαλακτερή βάση που λειαίνει τις κάθετες ραβδώσεις και προστατεύει την πλάκα από τις χρωστικές του βερνικιού. Αρκεί και μόνη της για ένα φυσικό, περιποιημένο αποτέλεσμα.', 'A milky base coat that smooths vertical ridges and protects the plate from polish pigments. On its own it gives a natural, groomed finish.', 'base_coat', array['nitrocellulose','silica','calcium pantothenate']::text[], '{}'::text[], array['global']::text[], array['all']::text[], array['all']::text[], array['nails']::text[], 'pm', 'low', 'Οι κάθετες ραβδώσεις πληθαίνουν με την ηλικία και συνήθως είναι αθώες. Μη λιμάρεις την πλάκα για να τις εξαφανίσεις.', 'Vertical ridges increase with age and are usually harmless. Do not file the plate down to get rid of them.'),
  ('2d5da43a-12c3-2182-55c6-ae659260af37'::uuid, 'cleanser-eye-makeup-biphase', 'Διφασικό ντεμακιγιάζ ματιών', 'Bi-phase eye make-up remover', 'Υγρό δύο φάσεων (λάδι και νερό) που ανακινείται πριν τη χρήση και διαλύει αδιάβροχη μάσκαρα και eyeliner χωρίς τρίψιμο. Το κρατάς με το βαμβάκι λίγα δευτερόλεπτα στα βλέφαρα και σκουπίζεις προς τα κάτω.', 'A two-phase liquid (oil and water) that you shake before use; it dissolves waterproof mascara and eyeliner without rubbing. Hold the soaked pad on the lids for a few seconds, then wipe downwards.', 'cleanser', array['isohexadecane','cyclopentasiloxane','cornflower water','panthenol']::text[], '{}'::text[], array['eu','global']::text[], array['women']::text[], array['all']::text[], array['general']::text[], 'pm', 'low', 'Για φακούς επαφής, βγάλε πρώτα τους φακούς. Αν τα μάτια τσούζουν, προτίμησε σύνθεση χωρίς άρωμα.', 'If you wear contact lenses, take them out first. If your eyes sting, choose a fragrance-free formula.'),
  ('3604bd11-ee14-0816-a066-b9131b0d12bb'::uuid, 'cleanser-salicylic-wash', 'Καθαριστικό με σαλικυλικό οξύ', 'Salicylic acid face wash', 'Gel καθαρισμού με χαμηλή συγκέντρωση σαλικυλικού οξέος (BHA), που μένει λίγο στο δέρμα και βοηθά να μη φράζουν οι πόροι. Για λιπαρή επιδερμίδα με τάση ακμής, και για άντρες με τρίχες που μπαίνουν μέσα μετά το ξύρισμα.', 'A cleansing gel with a low level of salicylic acid (BHA) that sits on the skin briefly and helps keep pores clear. For oily, acne-prone skin, and for men who get ingrown hairs after shaving.', 'cleanser', array['salicylic acid','glycerin','zinc pca']::text[], array['another bha in the same session','very dry or broken skin']::text[], array['us','global']::text[], array['all']::text[], array['oily','combination']::text[], array['acne','pores','shaving']::text[], 'both', 'low', 'Άφησέ το 30–60 δευτερόλεπτα πριν το ξεπλύνεις. Αν το δέρμα ξεραίνεται, κράτα το μόνο για το βράδυ.', 'Leave it on for 30–60 seconds before rinsing. If your skin dries out, keep it for evenings only.'),
  ('6e282820-bf80-d2f6-74b6-40fefd09034f'::uuid, 'cleanser-syndet-bar', 'Πλάκα καθαρισμού χωρίς σαπούνι (syndet)', 'Soap-free cleansing bar (syndet)', 'Στερεό καθαριστικό με ήπιους συνθετικούς επιφανειοδραστικούς, με pH κοντά σε αυτό του δέρματος. Καθαρίζει σαν σαπούνι αλλά στεγνώνει πολύ λιγότερο, κρατάει μήνες και δεν θέλει πλαστική συσκευασία.', 'A solid cleanser made with mild synthetic surfactants at a pH close to the skin’s. It cleans like soap but dries far less, lasts for months and needs no plastic bottle.', 'cleanser', array['sodium cocoyl isethionate','stearic acid','glycerin']::text[], '{}'::text[], array['eu','global']::text[], array['all']::text[], array['normal','dry','combination','sensitive']::text[], array['general','hydration']::text[], 'both', 'low', 'Δεν είναι το ίδιο με το κλασικό σαπούνι: κοίτα να γράφει «χωρίς σαπούνι» ή «syndet». Φύλαξέ το σε σαπουνοθήκη που στραγγίζει.', 'It is not the same as ordinary soap: look for “soap-free” or “syndet” on the label. Keep it on a draining dish.'),
  ('53a85f50-ef9e-0b1a-5f08-a2712a2808f5'::uuid, 'exfoliant-mandelic', 'Ήπιο απολεπιστικό με μανδελικό οξύ', 'Gentle mandelic acid exfoliant', 'AHA με μεγάλο μόριο που μπαίνει πιο αργά στο δέρμα, γι’ αυτό ερεθίζει λιγότερο από το γλυκολικό. Επιλογή για ευαίσθητη ή σκουρόχρωμη επιδερμίδα με κηλίδες και τάση ακμής, μία με δύο φορές την εβδομάδα.', 'An AHA with a large molecule that enters the skin more slowly, so it irritates less than glycolic acid. An option for sensitive or darker skin with marks and breakouts, once or twice a week.', 'exfoliant', array['mandelic acid','lactobionic acid','glycerin']::text[], array['retinoids in the same session','other acids in the same session']::text[], array['eu','us']::text[], array['all']::text[], array['sensitive','combination','oily','normal']::text[], array['texture','pigmentation','acne']::text[], 'pm', 'mid', 'Ακόμα και ήπια, τα οξέα κάνουν το δέρμα πιο ευαίσθητο στον ήλιο: αντηλιακό το επόμενο πρωί. Σε ενεργή ροδόχρου, ρώτα πρώτα δερματολόγο.', 'Even gentle acids make the skin more sun-sensitive: sunscreen the next morning. With active rosacea, ask a dermatologist first.'),
  ('8cee7701-2000-79b8-68c4-7f954d7735dc'::uuid, 'eye-cream-peptide', 'Κρέμα ματιών με πεπτίδια', 'Peptide eye cream', 'Ελαφριά κρέμα για τη λεπτή περιοχή των ματιών, με πεπτίδια, γλυκερίνη και κεραμίδια, χωρίς ρετινοειδή. Ενυδατώνει τις λεπτές γραμμές και ταιριάζει σε όποιον δεν αντέχει ρετινάλη γύρω από τα μάτια.', 'A light cream for the delicate eye area with peptides, glycerin and ceramides, no retinoids. It plumps fine lines with moisture and suits anyone who cannot tolerate retinal around the eyes.', 'eye', array['acetyl hexapeptide-8','palmitoyl tripeptide-1','glycerin','ceramides']::text[], '{}'::text[], array['global','kr']::text[], array['all']::text[], array['all']::text[], array['aging','hydration']::text[], 'both', 'mid', 'Μια ποσότητα όσο ένα κόκκος ρυζιού αρκεί για τα δύο μάτια. Ταμπονάρισε με τον παράμεσο, χωρίς να τραβάς το δέρμα.', 'A rice-grain amount is enough for both eyes. Tap it in with the ring finger, without pulling the skin.'),
  ('2ac89425-545d-0ac2-9dd3-f3c7a04e25e9'::uuid, 'eye-patch-hydrogel', 'Επιθέματα hydrogel για τα μάτια', 'Hydrogel eye patches', 'Δροσερά επιθέματα σε σχήμα μισοφέγγαρου, εμποτισμένα με ενυδατικά και καφεΐνη, κλασικά της κορεατικής περιποίησης. Μένουν 15–20 λεπτά κάτω από τα μάτια και δίνουν πρόσκαιρη φρεσκάδα το πρωί.', 'Cooling crescent-shaped patches soaked in humectants and caffeine, a Korean skincare classic. They stay under the eyes for 15–20 minutes and give a temporary fresh look in the morning.', 'eye', array['caffeine','glycerin','hyaluronic acid','niacinamide']::text[], '{}'::text[], array['kr']::text[], array['women','all']::text[], array['all']::text[], array['hydration','general']::text[], 'am', 'mid', 'Το αποτέλεσμα είναι προσωρινό: ο ύπνος και το αλάτι κάνουν περισσότερα για τις σακούλες. Μην τα ξαναχρησιμοποιείς.', 'The effect is temporary: sleep and salt do more for puffiness. Do not reuse them.'),
  ('bc8d9bd8-44a1-c9ad-9837-438223074e69'::uuid, 'hand-cream-spf', 'Κρέμα χεριών με SPF', 'Hand cream with SPF', 'Μη λιπαρή κρέμα χεριών με SPF 30 ή περισσότερο, για το πρωί και πριν από το ημιμόνιμο με λάμπα. Τα χέρια παίρνουν ήλιο όλη μέρα στο τιμόνι και στο κινητό, και δείχνουν την ηλικία νωρίς.', 'A non-greasy hand cream with SPF 30 or more, for mornings and before a gel manicure under a lamp. Hands catch sun all day on the steering wheel and the phone, and show age early.', 'hand_cream', array['zinc oxide','ethylhexyl triazone','glycerin','niacinamide']::text[], '{}'::text[], array['eu','us','global']::text[], array['women','all']::text[], array['all']::text[], array['hands','sun','pigmentation']::text[], 'am', 'mid', 'Ανανέωσέ τη μετά από κάθε πλύσιμο χεριών, γιατί το νερό την παίρνει. Μην ξεχνάς τη ράχη της παλάμης.', 'Reapply after every hand wash, because water takes it off. Do not forget the backs of the hands.'),
  ('50b5d64d-a494-b4a9-8b57-0783ad07a48f'::uuid, 'lip-ointment-repair', 'Επανορθωτική αλοιφή χειλιών', 'Repairing lip ointment', 'Απλή αλοιφή χωρίς άρωμα, με βαζελίνη, λανολίνη ή κερί, για σκασμένα χείλη από κρύο, αέρα ή ρετινοειδή. Πυκνότερη από ένα στικ και χωρίς γεύσεις που σε κάνουν να γλείφεις τα χείλη.', 'A plain, fragrance-free ointment with petrolatum, lanolin or wax for lips cracked by cold, wind or retinoids. Thicker than a stick, and without flavours that make you lick your lips.', 'lip', array['petrolatum','lanolin','beeswax','dexpanthenol']::text[], array['menthol, camphor or flavourings on cracked lips']::text[], array['eu','global']::text[], array['all']::text[], array['all']::text[], array['hydration']::text[], 'both', 'low', 'Τη μέρα, στον ήλιο, προτίμησε στικ με SPF. Αν οι γωνίες των χειλιών σκάνε συνέχεια, δείξ’ τες σε γιατρό.', 'By day in the sun, choose a stick with SPF instead. If the corners of the mouth keep cracking, show them to a doctor.'),
  ('5e65f8a7-587b-b23e-797f-00a944e78a38'::uuid, 'moisturizer-after-sun-gel', 'Gel για μετά τον ήλιο με αλόη και πανθενόλη', 'After-sun gel with aloe and panthenol', 'Δροσερό, ελαφρύ gel χωρίς άρωμα για δέρμα που ζεστάθηκε στον ήλιο, με αλόη, πανθενόλη και γλυκερίνη. Φύλαξέ το στο ψυγείο το καλοκαίρι για επιπλέον δροσιά.', 'A cool, light, fragrance-free gel for skin that has had too much sun, with aloe, panthenol and glycerin. Keep it in the fridge in summer for extra cooling.', 'moisturizer', array['aloe barbadensis leaf juice','panthenol','glycerin','allantoin']::text[], array['menthol or alcohol-heavy formulas on burnt skin']::text[], array['global']::text[], array['all']::text[], array['all']::text[], array['sun','redness','hydration']::text[], 'both', 'low', 'Δεν «θεραπεύει» το έγκαυμα και δεν αντικαθιστά το αντηλιακό. Φουσκάλες, πυρετός ή ζάλη θέλουν γιατρό.', 'It does not “heal” a burn and does not replace sunscreen. Blisters, fever or dizziness need a doctor.'),
  ('ec770f74-3477-242a-f682-2e705cb8995f'::uuid, 'moisturizer-rich-lipid-mature', 'Πλούσια κρέμα νυκτός για ώριμο δέρμα', 'Rich night cream for mature skin', 'Πυκνή κρέμα με λιπίδια (κεραμίδια, χοληστερόλη, λιπαρά οξέα), πεπτίδια και γλυκερίνη, για το δέρμα που γίνεται πιο ξηρό και λεπτό στην περιεμμηνόπαυση και μετά. Μπαίνει τελευταία το βράδυ.', 'A dense cream with lipids (ceramides, cholesterol, fatty acids), peptides and glycerin, for skin that turns drier and thinner around perimenopause and after. It goes on last at night.', 'moisturizer', array['ceramides','cholesterol','shea butter','palmitoyl tripeptide-1','glycerin']::text[], '{}'::text[], array['eu','global']::text[], array['women']::text[], array['dry','normal']::text[], array['aging','hydration']::text[], 'pm', 'mid', 'Η τιμή δεν δείχνει την αποτελεσματικότητα: τα βασικά λιπίδια υπάρχουν και σε φτηνές κρέμες φαρμακείου.', 'Price does not tell you how well it works: the key lipids are in inexpensive pharmacy creams too.'),
  ('2a853654-5134-4d8d-7005-2e52449d8c2f'::uuid, 'moisturizer-urea-face', 'Κρέμα προσώπου με ουρία 5 %', 'Face cream with 5 % urea', 'Ενυδατική με χαμηλή συγκέντρωση ουρίας, που τραβάει νερό στο δέρμα και μαλακώνει την τραχιά υφή. Καλή για πολύ ξηρό ή ώριμο δέρμα και για τις ξηρές περιοχές στον χειμώνα.', 'A moisturiser with a low level of urea, which draws water into the skin and softens rough texture. Good for very dry or mature skin and for dry patches in winter.', 'moisturizer', array['urea','glycerin','ceramides','lactic acid']::text[], array['rosacea-prone skin']::text[], array['eu']::text[], array['all']::text[], array['dry','normal']::text[], array['hydration','texture','aging']::text[], 'both', 'low', 'Σε σκασμένο ή ερεθισμένο δέρμα μπορεί να τσούξει. Σε ροδόχρου, οι δερματολόγοι προτείνουν να την αποφεύγεις.', 'It can sting on cracked or irritated skin. With rosacea, dermatologists suggest avoiding urea.'),
  ('959ebd3f-945e-9cbd-0d0f-950173b0b4c3'::uuid, 'nail-remover-gel-soak-off', 'Σετ αφαίρεσης ημιμόνιμου με ασετόνη (soak-off)', 'Gel polish soak-off kit (acetone)', 'Ασετόνη με βαμβάκια και αλουμινόχαρτο ή κλιπ, για να μαλακώσει το ημιμόνιμο ώστε να φύγει χωρίς τρόχισμα και ξύσιμο. Ο ήπιος τρόπος αφαίρεσης, αντί για το ξεκόλλημα με τα νύχια.', 'Acetone with cotton pads and foil or clips, to soften gel polish so it comes off without heavy filing or scraping. The gentle way to remove it, instead of peeling it off.', 'nail_remover', array['acetone','glycerin']::text[], array['open flame','acetone allergy']::text[], array['global']::text[], array['women','all']::text[], array['all']::text[], array['nails']::text[], 'pm', 'low', 'Λίμαρε ελαφρά μόνο τη γυαλιστερή επιφάνεια, άφησε 10–15 λεπτά και σπρώξε απαλά με ξυλάκι. Μετά, λάδι επωνυχίων και κρέμα χεριών.', 'File only the shiny top coat lightly, wait 10–15 minutes and nudge it off with a wooden stick. Then cuticle oil and hand cream.'),
  ('8c5924b5-0be7-741e-7456-134475b3bf75'::uuid, 'nail-treatment-hydrating-serum', 'Ενυδατική θεραπεία νυχιών', 'Hydrating nail treatment', 'Ορός ή κρέμα για την πλάκα του νυχιού με υγροσκοπικά (γλυκερίνη, ουρία) και ουσίες που κλείνουν την υγρασία μέσα (λανολίνη, βαζελίνη). Για νύχια που σχίζονται σε στρώσεις επειδή στεγνώνουν, όχι επειδή είναι «μαλακά».', 'A serum or cream for the nail plate with humectants (glycerin, urea) and occlusives that lock moisture in (lanolin, petrolatum). For nails that split into layers because they dry out, not because they are “soft”.', 'nail_treatment', array['glycerin','urea','lanolin','petrolatum','phospholipids']::text[], '{}'::text[], array['eu','global']::text[], array['all']::text[], array['all']::text[], array['nails','hydration']::text[], 'pm', 'low', 'Δούλεψέ το στο νύχι και στο δέρμα γύρω του κάθε βράδυ, για μήνες. Αν τα νύχια αλλάζουν χρώμα ή σχήμα, δείξ’ τα σε γιατρό.', 'Work it into the nail and the skin around it every night, for months. If nails change colour or shape, show them to a doctor.'),
  ('65ff5d11-3514-6e9d-0d7a-c356fe839aad'::uuid, 'serum-arbutin-kojic', 'Ορός λάμψης με άλφα-αρμπουτίνη ή κογικό οξύ', 'Brightening serum with alpha-arbutin or kojic acid', 'Ορός για ανομοιόμορφο τόνο και καφέ κηλίδες, με ουσίες που φρενάρουν την παραγωγή μελανίνης. Στην ΕΕ τα όρια είναι 2 % άλφα-αρμπουτίνη και 1 % κογικό οξύ σε προϊόντα προσώπου.', 'A serum for uneven tone and brown spots, with ingredients that slow melanin production. In the EU the caps are 2 % alpha-arbutin and 1 % kojic acid in face products.', 'serum', array['alpha-arbutin','kojic acid','niacinamide','licorice root extract']::text[], '{}'::text[], array['eu','kr','jp']::text[], array['women','all']::text[], array['normal','combination','oily','dry']::text[], array['pigmentation']::text[], 'both', 'mid', 'Χωρίς καθημερινό αντηλιακό οι κηλίδες ξαναγυρίζουν. Το κογικό οξύ ερεθίζει κάποιες επιδερμίδες: κάνε πρώτα τεστ.', 'Without daily sunscreen the spots come back. Kojic acid irritates some skin: patch test first.'),
  ('4b230a2f-177f-5417-da4f-2fd9b1b115dc'::uuid, 'serum-bakuchiol', 'Ορός μπακουχιόλης', 'Bakuchiol serum', 'Φυτικό συστατικό (από τον σπόρο Psoralea corylifolia) που δεν είναι ρετινοειδές, αλλά σε μικρές μελέτες έδωσε αποτελέσματα κοντά σε αυτά της ρετινόλης στις λεπτές γραμμές, με λιγότερο ερεθισμό. Επιλογή για όσους δεν ανέχονται τη ρετινόλη.', 'A plant ingredient (from Psoralea corylifolia seeds) that is not a retinoid, yet in small studies gave results close to retinol on fine lines, with less irritation. An option for those who cannot tolerate retinol.', 'serum', array['bakuchiol','squalane','tocopherol']::text[], '{}'::text[], array['us','eu','global']::text[], array['all']::text[], array['sensitive','dry','normal','combination']::text[], array['aging','texture']::text[], 'both', 'mid', 'Τα στοιχεία είναι λιγότερα από της ρετινόλης. «Φυτικό» δεν σημαίνει ελεγμένο στην εγκυμοσύνη: ρώτα τον γιατρό σου πριν το χρησιμοποιήσεις τότε.', 'The evidence is thinner than retinol’s. “Plant-based” does not mean tested in pregnancy: ask your doctor before using it then.'),
  ('da215a4f-6e33-0440-d006-d2ab78c650e3'::uuid, 'serum-panthenol-barrier', 'Καταπραϋντικός ορός με πανθενόλη και κεραμίδια', 'Soothing panthenol and ceramide serum', 'Απλός ορός επανόρθωσης του φραγμού, με προβιταμίνη B5, κεραμίδια και γλυκερίνη. Για δέρμα που τσούζει από υπερβολικά «ενεργά», μετά τον ήλιο ή τον χειμώνα με το καλοριφέρ.', 'A simple barrier-repair serum with provitamin B5, ceramides and glycerin. For skin that stings from too many actives, after the sun, or in winter with the heating on.', 'serum', array['panthenol','ceramides','glycerin','allantoin']::text[], '{}'::text[], array['eu','global']::text[], array['all']::text[], array['sensitive','dry','all']::text[], array['redness','hydration']::text[], 'both', 'low', 'Όταν ο φραγμός έχει «καεί», σταμάτα τα οξέα και τα ρετινοειδή για μία με δύο εβδομάδες και κράτα μόνο αυτόν και κρέμα.', 'When the barrier is “burnt”, stop acids and retinoids for a week or two and keep only this and a cream.'),
  ('ad7354e7-89b2-191e-05a7-04dfa78050af'::uuid, 'serum-retinal', 'Ορός ρετινάλης (ρετιναλδεΰδης)', 'Retinal (retinaldehyde) serum', 'Ρετινοειδές χωρίς συνταγή, ένα βήμα πιο κοντά στη δραστική μορφή από τη ρετινόλη, γι’ αυτό δουλεύει σε μικρότερες συγκεντρώσεις (0,05–0,1 %). Για λεπτές γραμμές, υφή και κηλίδες, μόνο το βράδυ.', 'A non-prescription retinoid one step closer to the active form than retinol, so it works at lower strengths (0.05–0.1 %). For fine lines, texture and dark spots, evenings only.', 'serum', array['retinal','niacinamide','squalane']::text[], array['aha in the same session','bha in the same session','benzoyl peroxide','pregnancy and breastfeeding']::text[], array['eu','global']::text[], array['all']::text[], array['normal','dry','combination','oily']::text[], array['aging','texture','pigmentation']::text[], 'pm', 'high', 'Ξεκίνα δύο βράδια την εβδομάδα και ανέβαινε σιγά σιγά. Όχι στην εγκυμοσύνη και τον θηλασμό, και αντηλιακό κάθε πρωί.', 'Start two nights a week and build up slowly. Not in pregnancy or breastfeeding, and sunscreen every morning.'),
  ('9bcf334e-0db9-019e-5080-9ada210dba8a'::uuid, 'serum-tranexamic-acid', 'Ορός τρανεξαμικού οξέος', 'Tranexamic acid serum', 'Ορός για κηλίδες και μέλασμα, συνήθως 2–5 % τρανεξαμικό οξύ, συχνά μαζί με νιασιναμίδη. Οι μελέτες σε μέλασμα δείχνουν όφελος σε 8–12 εβδομάδες, αρκεί να υπάρχει καθημερινά αντηλιακό.', 'A serum for dark patches and melasma, usually 2–5 % tranexamic acid, often with niacinamide. Studies in melasma show benefit within 8–12 weeks, provided daily sunscreen goes with it.', 'serum', array['tranexamic acid','niacinamide','glycerin']::text[], '{}'::text[], array['kr','eu','global']::text[], array['women','all']::text[], array['all']::text[], array['pigmentation']::text[], 'both', 'mid', 'Το τρανεξαμικό από το στόμα είναι φάρμακο με συνταγή και άλλους κινδύνους· ο ορός είναι καλλυντικό. Για επίμονο μέλασμα, το πλάνο το φτιάχνει δερματολόγος.', 'Oral tranexamic acid is a prescription drug with different risks; the serum is a cosmetic. For stubborn melasma, a dermatologist builds the plan.'),
  ('16ce05bf-2389-dc2b-cb38-3e8ace51f781'::uuid, 'shaving-gel-clear-sensitive', 'Διάφανο gel ξυρίσματος για ευαίσθητο δέρμα', 'Clear shaving gel for sensitive skin', 'Gel ξυρίσματος χωρίς άρωμα που δεν αφρίζει πολύ, οπότε βλέπεις πού περνάς τη λεπίδα, ιδανικό για περίγραμμα γενειάδας. Ενυδατώνει την τρίχα και βοηθά τη λεπίδα να γλιστράει.', 'A fragrance-free shaving gel that barely foams, so you can see where the blade goes, ideal for shaping a beard line. It moisturises the hair and helps the blade glide.', 'shaving', array['glycerin','aloe barbadensis leaf juice','allantoin']::text[], '{}'::text[], array['global']::text[], array['men','all']::text[], array['sensitive','normal','dry','all']::text[], array['shaving','redness']::text[], 'both', 'low', 'Ταιριάζει και για ξύρισμα ποδιών ή μασχάλης. Ξέπλενε τη λεπίδα μετά από κάθε πέρασμα.', 'It works for legs and underarms too. Rinse the blade after every stroke.'),
  ('fad11454-e1d3-3825-13c8-ac1ab50289b0'::uuid, 'shaving-ingrown-hair-lotion', 'Λοσιόν κατά των τριχών που μπαίνουν μέσα', 'Ingrown-hair lotion', 'Λοσιόν με ήπια οξέα (σαλικυλικό, γλυκολικό) για τις περιοχές που ξυρίζονται ή αποτριχώνονται, ώστε η τρίχα να βγαίνει χωρίς να εγκλωβίζεται. Μπαίνει το βράδυ, όχι αμέσως μετά το ξύρισμα.', 'A lotion with mild acids (salicylic, glycolic) for shaved or waxed areas, so hairs grow out instead of getting trapped. It goes on in the evening, not right after shaving.', 'shaving', array['salicylic acid','glycolic acid','witch hazel']::text[], array['freshly shaved or broken skin','retinoids in the same session']::text[], array['us','global']::text[], array['men','women']::text[], array['normal','oily','combination']::text[], array['shaving','acne','texture']::text[], 'pm', 'mid', 'Αν τα σπυράκια από το ξύρισμα επιμένουν ή αφήνουν σκούρα σημάδια, ρώτα δερματολόγο. Αντηλιακό την επομένη στις περιοχές που φαίνονται.', 'If razor bumps persist or leave dark marks, ask a dermatologist. Sunscreen the next day on any exposed areas.'),
  ('b83b92cd-a9c0-ade0-eda2-5b8a379ea9aa'::uuid, 'sunscreen-fluid-oil-control', 'Ματ αντηλιακό fluid για λιπαρή επιδερμίδα', 'Matte sunscreen fluid for oily skin', 'Πολύ ρευστό αντηλιακό SPF 50 με απορροφητικές πούδρες και σήμα «μη φαγεσωρογόνο», που δεν γυαλίζει και δεν βαραίνει. Για λιπαρό δέρμα με τάση ακμής και για άντρες που μισούν την αίσθηση της κρέμας.', 'A very runny SPF 50 sunscreen with oil-absorbing powders and a non-comedogenic label, so it does not shine or feel heavy. For oily, acne-prone skin and for men who hate the feel of cream.', 'sunscreen', array['bis-ethylhexyloxyphenol methoxyphenyl triazine','silica','niacinamide','zinc pca']::text[], '{}'::text[], array['eu','global']::text[], array['all','men']::text[], array['oily','combination']::text[], array['sun','acne','pores']::text[], 'am', 'mid', 'Ανακίνησε καλά πριν τη χρήση. Η ματ υφή δεν σημαίνει λιγότερη ποσότητα: δύο δάχτυλα για πρόσωπο και λαιμό.', 'Shake well before use. A matte finish does not mean less product: two finger-lengths for face and neck.'),
  ('17f36883-1dd9-f957-2f75-801f2fa85a8c'::uuid, 'sunscreen-powder-touch-up', 'Πούδρα με SPF για ανανέωση πάνω από το μακιγιάζ', 'SPF powder for top-ups over make-up', 'Ορυκτή πούδρα με πινέλο, για να ανανεώνεις την προστασία στη μέση της μέρας χωρίς να χαλάσεις το μακιγιάζ. Είναι συμπλήρωμα του κανονικού αντηλιακού το πρωί, όχι υποκατάστατο.', 'A mineral powder with a built-in brush, for topping up protection mid-day without ruining make-up. It complements the morning sunscreen; it does not replace it.', 'sunscreen', array['zinc oxide','titanium dioxide','iron oxides','silica']::text[], '{}'::text[], array['us','global']::text[], array['women']::text[], array['oily','combination','normal']::text[], array['sun','pores']::text[], 'am', 'high', 'Για να φτάσεις το SPF της ετικέτας χρειάζεται πολύ περισσότερη πούδρα απ’ όση βάζει κανείς. Πέρασε πολλές φορές, σε όλο το πρόσωπο.', 'Reaching the label SPF takes far more powder than people use. Go over the whole face several times.'),
  ('74410ec7-a473-213b-98c2-a81bffe5180e'::uuid, 'sunscreen-primer-spf', 'Βάση μακιγιάζ (primer) με SPF', 'Make-up primer with SPF', 'Λεία βάση που «στρώνει» το δέρμα για το μακιγιάζ και έχει δηλωμένο SPF 30–50. Λειτουργεί ως αντηλιακό μόνο αν μπει σε πλήρη ποσότητα, όπως ένα κανονικό αντηλιακό.', 'A smoothing base that preps the skin for make-up and carries a declared SPF 30–50. It works as sunscreen only if applied in full amount, like a regular sunscreen.', 'sunscreen', array['ethylhexyl triazone','dimethicone','silica','glycerin']::text[], '{}'::text[], array['eu','kr','global']::text[], array['women']::text[], array['normal','combination','oily']::text[], array['sun','pores']::text[], 'am', 'mid', 'Αν βάζεις λίγο, όπως βάζουμε συνήθως το primer, η προστασία πέφτει πολύ. Σε μέρες με πολύ ήλιο, βάλε πρώτα αντηλιακό.', 'Used sparingly, as primer usually is, the protection drops a lot. On very sunny days, put sunscreen on first.'),
  ('e3036af9-e4bb-74bf-7819-00cccb0550d6'::uuid, 'sunscreen-spray-reapply', 'Αντηλιακό σπρέι για ανανέωση', 'Sunscreen spray for reapplying', 'Λεπτό, διάφανο σπρέι για να ανανεώνεις την προστασία στην παραλία, στον λαιμό, στα αυτιά και στο σώμα. Για το πρόσωπο ψέκασε στις παλάμες και άπλωσε, ποτέ κατευθείαν στο πρόσωπο.', 'A fine, clear spray to top up protection at the beach on the neck, ears and body. For the face, spray into your palms and spread — never straight at the face.', 'sunscreen', array['bis-ethylhexyloxyphenol methoxyphenyl triazine','octocrylene','alcohol denat']::text[], array['open flame until dry']::text[], array['eu','us','global']::text[], array['all']::text[], array['normal','oily','combination','all']::text[], array['sun']::text[], 'am', 'mid', 'Ψέκασε μέχρι το δέρμα να γυαλίσει και άπλωσε με το χέρι — ο αέρας παίρνει μεγάλο μέρος. Μην το εισπνέεις.', 'Spray until the skin glistens and rub it in — the wind takes a lot of it. Do not breathe it in.'),
  ('540b1d51-0740-fa75-9aa6-71f0c91a999a'::uuid, 'sunscreen-tinted-iron-oxide', 'Αντηλιακό με χρώμα (οξείδια του σιδήρου)', 'Tinted sunscreen with iron oxides', 'Ορυκτό αντηλιακό SPF 30–50 με χρωστικές οξειδίων του σιδήρου, που προστατεύει και από το ορατό φως, κάτι που μετράει στο μέλασμα και τις κηλίδες. Δίνει ελαφριά κάλυψη, οπότε σε πολλές μέρες αντικαθιστά το make-up.', 'A mineral SPF 30–50 sunscreen with iron oxide pigments that also shield against visible light, which matters for melasma and dark spots. It gives light coverage, so on many days it replaces foundation.', 'sunscreen', array['zinc oxide','titanium dioxide','iron oxides']::text[], '{}'::text[], array['eu','us','global']::text[], array['women','all']::text[], array['all']::text[], array['sun','pigmentation','redness']::text[], 'am', 'mid', 'Οι αποχρώσεις διαφέρουν πολύ: δοκίμασε στο σαγόνι στο φως της μέρας. Βάλε όση ποσότητα θα έβαζες από άχρωμο αντηλιακό.', 'Shades vary a lot: test on the jawline in daylight. Apply as much as you would of an untinted sunscreen.'),
  ('3123cf04-881a-1da5-5490-b943b02af17d'::uuid, 'toner-thermal-water-mist', 'Ιαματικό νερό σε σπρέι', 'Thermal spring water mist', 'Νερό από ιαματικές πηγές σε σπρέι, κλασικό των ευρωπαϊκών φαρμακείων, για δροσιά και ανακούφιση σε ευαίσθητο ή ερεθισμένο δέρμα, μετά τον ήλιο ή μετά το ξύρισμα. Δεν ενυδατώνει από μόνο του: σκούπισε την περίσσεια και βάλε κρέμα από πάνω.', 'Spring water in a spray, a European pharmacy classic, for a cooling, soothing moment on sensitive or irritated skin, after the sun or after shaving. On its own it does not moisturise: blot the excess and follow with a cream.', 'toner', array['thermal spring water','nitrogen']::text[], '{}'::text[], array['eu']::text[], array['all']::text[], array['sensitive','dry','normal','all']::text[], array['redness','sun','shaving']::text[], 'both', 'low', 'Αν το αφήσεις να εξατμιστεί μόνο του στο πρόσωπο, το δέρμα μπορεί να στεγνώσει περισσότερο. Ταμπονάρισε μετά από λίγα δευτερόλεπτα.', 'Left to evaporate on its own, it can leave the skin drier than before. Pat it off after a few seconds.')
insert into hygieia.skincare_routines (id, slug, area, name_el, name_en, audience, skin_type, region, time, intro_el, intro_en, steps, duration_min) values
  ('f2db579b-f561-4b94-cb3a-3b77c7db83e8'::uuid, 'face-all-all-am-eu-budget', 'face', 'Οικονομική πρωινή ρουτίνα: τρία προϊόντα', 'Budget morning routine: three products', 'all', 'all', 'eu', 'am', 'Καθαριστικό, ενυδατική, αντηλιακό: τα τρία βήματα που κάνουν τη μεγαλύτερη διαφορά, όλα από τη χαμηλή κατηγορία τιμής του φαρμακείου ή του σούπερ μάρκετ. Η τιμή δεν δείχνει την αποτελεσματικότητα — η καθημερινή χρήση τη δείχνει.', 'Cleanser, moisturiser, sunscreen: the three steps that make the most difference, all from the low price band of the pharmacy or supermarket. Price does not show how well a product works — daily use does.', '[{"order":1,"product_type_slug":"cleanser-syndet-bar","note_el":"Μία πλάκα κρατάει μήνες· αφρός στις παλάμες, όχι πάνω στο πρόσωπο.","note_en":"One bar lasts months; lather in your palms, not on the face.","optional":false},{"order":2,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Η μεγάλη συσκευασία με αντλία συχνά κάνει και για το σώμα.","note_en":"The big pump tub often works for the body too.","optional":false},{"order":3,"product_type_slug":"sunscreen-eu-modern-filters","note_el":"Το μεγάλο μπουκάλι για όλη την οικογένεια βγαίνει φτηνότερο ανά ml.","note_en":"The large family bottle works out cheaper per ml.","optional":false},{"order":4,"product_type_slug":"lip-balm-spf","note_el":"Ένα φτηνό στικ με SPF στην τσέπη.","note_en":"A cheap SPF stick in your pocket.","optional":true}]'::jsonb, 3),
  ('6f4ffac9-bc6b-96c0-fec7-4c0d62c5507b'::uuid, 'face-all-all-am-eu-greek-summer-beach', 'face', 'Πρωινή ρουτίνα για μέρα στην παραλία — ελληνικό καλοκαίρι', 'Morning routine for a beach day — Greek summer', 'all', 'all', 'eu', 'am', 'Από τον Μάιο ως τον Σεπτέμβριο ο δείκτης UV στην Ελλάδα φτάνει συχνά το 8–10. Ελαφριές υφές, αντηλιακό με υψηλή UVA, στικ στην τσάντα για ανανέωση κάθε δύο ώρες και μετά από κάθε βουτιά, και σκιά γύρω στο μεσημέρι, όταν ο δείκτης UV είναι υψηλός.', 'From May to September the UV index in Greece often reaches 8–10. Light textures, a high-UVA sunscreen, a stick in the bag to reapply every two hours and after every swim, and shade around midday, when the UV index is high.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Γρήγορο πλύσιμο με δροσερό νερό.","note_en":"A quick wash with cool water.","optional":false},{"order":2,"product_type_slug":"serum-vitamin-c","note_el":"Επιπλέον αντιοξειδωτικά κάτω από το αντηλιακό.","note_en":"Extra antioxidants under the sunscreen.","optional":true},{"order":3,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Με την υγρασία του καλοκαιριού συχνά αρκεί το αντηλιακό· βάλε το μόνο αν το δέρμα τραβάει.","note_en":"In summer humidity the sunscreen is often enough; use this only if your skin feels tight.","optional":true},{"order":4,"product_type_slug":"sunscreen-eu-modern-filters","note_el":"SPF 50, ανθεκτικό στο νερό, 15 λεπτά πριν βγεις· και στα αυτιά και τον σβέρκο.","note_en":"SPF 50, water-resistant, 15 minutes before going out; ears and back of the neck too.","optional":false},{"order":5,"product_type_slug":"sunscreen-stick-reapply","note_el":"Στην τσάντα: μύτη, ζυγωματικά, αυτιά, μετά από κάθε μπάνιο και σκούπισμα.","note_en":"In the bag: nose, cheekbones, ears, after every swim and towel-off.","optional":false},{"order":6,"product_type_slug":"lip-balm-spf","note_el":"Ανανέωση κάθε φορά που τρως ή πίνεις.","note_en":"Reapply every time you eat or drink.","optional":false}]'::jsonb, 5),
  ('8c87fee3-5209-dc4c-f97f-9058757e3a63'::uuid, 'face-all-all-pm-eu-after-sun', 'face', 'Βραδινή ρουτίνα μετά από πολύ ήλιο', 'Evening routine after too much sun', 'all', 'all', 'eu', 'pm', 'Όταν το δέρμα κοκκίνισε και «καίει»: δροσιά, ενυδάτωση χωρίς άρωμα και διάλειμμα από οξέα και ρετινοειδή μέχρι να ηρεμήσει. Μην σπας φουσκάλες και μην βάζεις πάγο απευθείας. Φουσκάλες σε μεγάλη έκταση, πυρετός, ρίγος ή ζάλη θέλουν γιατρό.', 'When the skin has turned red and feels hot: cool it, moisturise without fragrance, and pause acids and retinoids until it settles. Do not pop blisters or put ice straight on the skin. Widespread blisters, fever, chills or dizziness need a doctor.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Δροσερό ντους πρώτα· μετά ήπιος καθαρισμός με δροσερό νερό, χωρίς τρίψιμο.","note_en":"A cool shower first; then a gentle cleanse with cool water, no rubbing.","optional":false},{"order":2,"product_type_slug":"toner-thermal-water-mist","note_el":"Για δροσιά· ταμπονάρισε μετά από λίγα δευτερόλεπτα.","note_en":"For cooling; blot it after a few seconds.","optional":true},{"order":3,"product_type_slug":"serum-panthenol-barrier","note_el":"Σε νωπό δέρμα, αν το πρόσωπο τσούζει.","note_en":"On damp skin, if your face stings.","optional":true},{"order":4,"product_type_slug":"moisturizer-after-sun-gel","note_el":"Παχιά στρώση, και ξανά όποτε το δέρμα ζεσταίνεται· πιες και άφθονο νερό.","note_en":"A thick layer, again whenever the skin heats up; drink plenty of water too.","optional":false}]'::jsonb, 5),
  ('5ce38ffd-b9a3-17d1-d2aa-4f503cb3adcb'::uuid, 'face-all-all-pm-eu-budget', 'face', 'Οικονομική βραδινή ρουτίνα', 'Budget evening routine', 'all', 'all', 'eu', 'pm', 'Το βράδυ το δέρμα θέλει καθαρισμό και ενυδάτωση· τα υπόλοιπα είναι προαιρετικά. Αν θέλεις ένα μόνο «ενεργό», η νιασιναμίδη είναι φτηνή και ταιριάζει σχεδόν με όλα.', 'At night the skin needs cleansing and moisture; the rest is optional. If you want just one active, niacinamide is cheap and pairs with almost everything.', '[{"order":1,"product_type_slug":"cleanser-micellar-water","note_el":"Μόνο για μακιγιάζ ή αντηλιακό ανθεκτικό στο νερό.","note_en":"Only for make-up or water-resistant sunscreen.","optional":true},{"order":2,"product_type_slug":"cleanser-syndet-bar","note_el":"Η ίδια πλάκα με το πρωί.","note_en":"The same bar as in the morning.","optional":false},{"order":3,"product_type_slug":"serum-niacinamide","note_el":"Λίγες σταγόνες· το 5 % αρκεί, δεν χρειάζεται 20 %.","note_en":"A few drops; 5 % is enough, there is no need for 20 %.","optional":true},{"order":4,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Η ίδια κρέμα με το πρωί, λίγο πιο γενναία.","note_en":"The same cream as the morning, a little more generously.","optional":false}]'::jsonb, 4),
  ('22497444-1427-5e9c-b66c-57799b50a3dd'::uuid, 'face-all-sensitive-am-eu-rosacea', 'face', 'Πρωινή ρουτίνα για ευαίσθητο δέρμα με τάση για ροδόχρου', 'Morning routine for sensitive, rosacea-prone skin', 'all', 'sensitive', 'eu', 'am', 'Λίγα προϊόντα χωρίς άρωμα, οινόπνευμα ή μενθόλη, και ορυκτό αντηλιακό, γιατί ο ήλιος είναι από τις πιο συχνές αιτίες έξαρσης. Αν έχεις διάγνωση ροδόχρου και φαρμακευτική αγωγή από δερματολόγο, η αγωγή μπαίνει πρώτη και η ενυδατική μετά.', 'A few products without fragrance, alcohol or menthol, and a mineral sunscreen, because sun is one of the most common flare triggers. If you have rosacea and a dermatologist’s prescription, the medicine goes on first and the moisturiser after.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Με τα δάχτυλα και χλιαρό νερό, χωρίς πανάκι ή σφουγγάρι· ταμπονάρισμα για στέγνωμα.","note_en":"With fingertips and lukewarm water, no washcloth or sponge; pat dry.","optional":false},{"order":2,"product_type_slug":"toner-thermal-water-mist","note_el":"Λίγο σπρέι όταν το δέρμα καίει, και ταμπονάρισμα μετά από λίγα δευτερόλεπτα.","note_en":"A light spray when the skin feels hot, blotted after a few seconds.","optional":true},{"order":3,"product_type_slug":"serum-azelaic-acid","note_el":"Για κοκκινίλα και σπυράκια· ένα ελαφρύ τσίμπημα τις πρώτες εβδομάδες είναι συνηθισμένο.","note_en":"For redness and bumps; a slight tingle in the first weeks is common.","optional":true},{"order":4,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Κάθε μέρα, ακόμα κι αν το δέρμα είναι λιπαρό· χωρίς ουρία.","note_en":"Every day, even if your skin is oily; no urea.","optional":false},{"order":5,"product_type_slug":"sunscreen-mineral-zinc","note_el":"Οξείδιο του ψευδαργύρου ή/και διοξείδιο του τιτανίου, SPF 30+, και καπέλο.","note_en":"Zinc oxide and/or titanium dioxide, SPF 30+, and a hat.","optional":false}]'::jsonb, 5),
  ('79c1b9cf-c8ee-813b-8736-dfe75cf0cda2'::uuid, 'face-all-sensitive-pm-eu-rosacea', 'face', 'Βραδινή ρουτίνα για ευαίσθητο δέρμα με τάση για ροδόχρου', 'Evening routine for sensitive, rosacea-prone skin', 'all', 'sensitive', 'eu', 'pm', 'Το βράδυ ο στόχος είναι να ηρεμήσει το δέρμα: ήπιος καθαρισμός και επανόρθωση του φραγμού, χωρίς απολεπιστικά και scrub. Δοκίμαζε κάθε νέο προϊόν πρώτα στο εσωτερικό του μπράτσου για μία εβδομάδα.', 'In the evening the aim is to calm the skin: a gentle cleanse and barrier repair, no exfoliants or scrubs. Try every new product on the inside of your arm for a week first.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ένας καθαρισμός αρκεί· χωρίς καυτό νερό.","note_en":"One cleanse is enough; no hot water.","optional":false},{"order":2,"product_type_slug":"serum-centella-cica","note_el":"Πίεσε απαλά με τις παλάμες, χωρίς τρίψιμο.","note_en":"Press it in gently with your palms, no rubbing.","optional":true},{"order":3,"product_type_slug":"serum-panthenol-barrier","note_el":"Τις μέρες που το δέρμα τσούζει ή ξεφλουδίζει.","note_en":"On days when the skin stings or flakes.","optional":true},{"order":4,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Κρέμα αντί για λοσιόν ή gel — οι δερματολόγοι την προτιμούν στο ευαίσθητο δέρμα.","note_en":"A cream rather than a lotion or gel — dermatologists prefer it for sensitive skin.","optional":false}]'::jsonb, 4),
  ('84945c1f-c7a4-ea72-2d76-8081d90e656a'::uuid, 'face-men-dry-pm-eu-bakuchiol', 'face', 'Βραδινή αντιγηραντική ρουτίνα για άντρες χωρίς ρετινόλη', 'Men’s retinol-free anti-ageing evening routine', 'men', 'dry', 'eu', 'pm', 'Για όσους η ρετινόλη τσούζει ή ξεφλουδίζει: μπακουχιόλη, μια πλούσια κρέμα και λάδι για τη γενειάδα. Τέσσερα λεπτά πριν τον ύπνο· το αποτέλεσμα θέλει τρεις μήνες συνέπειας.', 'For men whose skin stings or peels with retinol: bakuchiol, a rich cream and beard oil. Four minutes before bed; results take three months of consistency.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ήπιος καθαρισμός, και στη γενειάδα.","note_en":"A gentle cleanse, through the beard too.","optional":false},{"order":2,"product_type_slug":"serum-bakuchiol","note_el":"Λίγες σταγόνες σε πρόσωπο και λαιμό.","note_en":"A few drops on face and neck.","optional":false},{"order":3,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Σε όλο το πρόσωπο, μέχρι τη γραμμή της γενειάδας.","note_en":"Over the whole face, up to the beard line.","optional":false},{"order":4,"product_type_slug":"eye-cream-peptide","note_el":"Για τις λεπτές ρυτίδες στις άκρες των ματιών.","note_en":"For crow’s feet.","optional":true},{"order":5,"product_type_slug":"beard-oil","note_el":"Δύο-τρεις σταγόνες στο δέρμα κάτω από τη γενειάδα.","note_en":"Two or three drops on the skin under the beard.","optional":true}]'::jsonb, 4),
  ('99020852-a593-7c14-d281-4326e4d783bc'::uuid, 'face-men-oily-pm-us-ingrown-hairs', 'face', 'Βραδινή ρουτίνα για τρίχες που μπαίνουν μέσα', 'Evening routine for ingrown hairs', 'men', 'oily', 'us', 'pm', 'Τα σπυράκια στον λαιμό και το σαγόνι μετά το ξύρισμα είναι συνήθως τρίχες που γύρισαν προς τα μέσα. Ένα ήπιο οξύ το βράδυ, μακριά από το ξύρισμα, βοηθά την τρίχα να βγαίνει. Μην τις τσιμπάς με τσιμπιδάκι· αν αφήνουν σημάδια ή μολύνονται, δερματολόγος.', 'Bumps on the neck and jaw after shaving are usually hairs that curled back in. A mild acid in the evening, well away from the shave, helps them grow out. Do not dig them out with tweezers; if they scar or get infected, see a dermatologist.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Καθαρισμός χωρίς τρίψιμο με πανάκι.","note_en":"A cleanse without scrubbing with a cloth.","optional":false},{"order":2,"product_type_slug":"shaving-ingrown-hair-lotion","note_el":"Με βαμβάκι στις περιοχές του ξυρίσματος· όχι σε σπασμένο δέρμα.","note_en":"With a cotton pad on the shaved areas; not on broken skin.","optional":false},{"order":3,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Λίγο, όταν στεγνώσει η λοσιόν.","note_en":"A little, once the lotion has dried.","optional":false},{"order":4,"product_type_slug":"treatment-hydrocolloid-patch","note_el":"Πάνω σε φουσκωμένο σπυράκι, για να μην το πειράζεις.","note_en":"Over a swollen bump, so you leave it alone.","optional":true}]'::jsonb, 4),
  ('79bec31f-f5d5-4538-f117-db7eade98645'::uuid, 'face-men-sensitive-am-eu-gentle-shave', 'face', 'Πρωινό ήπιο ξύρισμα για ευαίσθητο δέρμα', 'Gentle morning shave for sensitive skin', 'men', 'sensitive', 'eu', 'am', 'Για όσους κοκκινίζουν ή βγάζουν σπυράκια μετά το ξύρισμα: προϊόντα χωρίς άρωμα, ξυράφι με μία ή δύο λεπίδες, ξύρισμα με τη φορά της τρίχας και ενυδατική όσο το δέρμα είναι ακόμη νωπό. Και ορυκτό αντηλιακό στο τέλος, γιατί το φρεσκοξυρισμένο δέρμα καίγεται εύκολα.', 'For men who go red or get bumps after shaving: fragrance-free products, a single- or double-blade razor, shaving with the grain and moisturiser while the skin is still damp. And a mineral sunscreen at the end, because freshly shaved skin burns easily.', '[{"order":1,"product_type_slug":"cleanser-syndet-bar","note_el":"Στο τέλος του ντους, για να μαλακώσει η τρίχα.","note_en":"At the end of the shower, so the hair softens.","optional":false},{"order":2,"product_type_slug":"shaving-pre-shave-oil","note_el":"Λίγες σταγόνες αν η γενειάδα είναι σκληρή.","note_en":"A few drops if your stubble is coarse.","optional":true},{"order":3,"product_type_slug":"shaving-gel-clear-sensitive","note_el":"Λεπτή στρώση· βλέπεις το περίγραμμα και δεν ξαναπερνάς το ίδιο σημείο.","note_en":"A thin layer; you can see the line and avoid going over the same spot.","optional":false},{"order":4,"product_type_slug":"toner-thermal-water-mist","note_el":"Δροσερό ψέκασμα στην κοκκινίλα, και ταμπονάρισμα.","note_en":"A cool spritz on any redness, then blot.","optional":true},{"order":5,"product_type_slug":"shaving-aftershave-balm","note_el":"Βάλσαμο, όχι λοσιόν με οινόπνευμα.","note_en":"A balm, not an alcohol splash.","optional":false},{"order":6,"product_type_slug":"sunscreen-mineral-zinc","note_el":"Ορυκτό SPF 30+, και στα αυτιά και τον λαιμό.","note_en":"Mineral SPF 30+, on the ears and neck too.","optional":false}]'::jsonb, 10),
  ('d4693b4f-46d8-dec8-5ab3-7852f331eadc'::uuid, 'face-women-all-am-eu-melasma', 'face', 'Πρωινή ρουτίνα για μέλασμα και κηλίδες', 'Morning routine for melasma and dark spots', 'women', 'all', 'eu', 'am', 'Στο μέλασμα το πρωί κρίνει τα πάντα: ένας ορός που φρενάρει τη μελανίνη και, κυρίως, αντηλιακό με χρώμα που κόβει και το ορατό φως. Ανανέωση στη μέση της μέρας, ακόμα και με συννεφιά. Το μέλασμα ξαναγυρίζει εύκολα — το συνολικό πλάνο το φτιάχνει δερματολόγος.', 'With melasma the morning decides everything: a serum that slows melanin and, above all, a tinted sunscreen that also blocks visible light. Top it up mid-day, even on cloudy days. Melasma returns easily — a dermatologist builds the overall plan.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ήπιος καθαρισμός· ο ερεθισμός μπορεί να σκουρύνει τις κηλίδες.","note_en":"A gentle cleanse; irritation can darken the patches.","optional":false},{"order":2,"product_type_slug":"serum-tranexamic-acid","note_el":"Σε όλο το πρόσωπο, όχι μόνο στις κηλίδες· δώσε του 8–12 εβδομάδες.","note_en":"Over the whole face, not just the patches; give it 8–12 weeks.","optional":false},{"order":3,"product_type_slug":"serum-vitamin-c","note_el":"Αν το δέρμα το ανέχεται, μετά το τρανεξαμικό, πριν την κρέμα.","note_en":"If your skin tolerates it, after the tranexamic acid, before the cream.","optional":true},{"order":4,"product_type_slug":"moisturizer-emulsion-light","note_el":"Λίγη ποσότητα· αν το αντηλιακό σου ενυδατώνει αρκετά, παράλειψέ το.","note_en":"A small amount; skip it if your sunscreen moisturises enough.","optional":true},{"order":5,"product_type_slug":"sunscreen-tinted-iron-oxide","note_el":"Δύο δάχτυλα ποσότητα, μέχρι τους κροτάφους και το πάνω χείλος.","note_en":"Two finger-lengths, out to the temples and over the upper lip.","optional":false},{"order":6,"product_type_slug":"sunscreen-powder-touch-up","note_el":"Ανανέωση το μεσημέρι πάνω από το μακιγιάζ, με πολλά περάσματα.","note_en":"A mid-day top-up over make-up, with several passes.","optional":true}]'::jsonb, 6),
  ('01440f58-bae9-0bb7-b4b6-a1393b7f96c0'::uuid, 'face-women-all-am-eu-pregnancy-safe', 'face', 'Πρωινή ρουτίνα στην εγκυμοσύνη — χωρίς ρετινοειδή', 'Pregnancy morning routine — retinoid-free', 'women', 'all', 'eu', 'am', 'Λίγα, ήπια βήματα για την εγκυμοσύνη και τον θηλασμό: καμία ρετινόλη, ρετινάλη ή αδαπαλένη, και καθόλου υδροκινόνη. Το σημαντικότερο βήμα είναι το αντηλιακό με χρώμα, γιατί οι ορμόνες της εγκυμοσύνης ευνοούν το μέλασμα. Δείξε τα προϊόντα σου στον γυναικολόγο σου.', 'A few gentle steps for pregnancy and breastfeeding: no retinol, retinal or adapalene, and no hydroquinone. The most important step is a tinted sunscreen, because pregnancy hormones make melasma more likely. Show your products to your obstetrician.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ήπιος καθαρισμός με χλιαρό νερό· αν το δέρμα είναι ξηρό, αρκεί ένα ξέβγαλμα.","note_en":"A gentle cleanse with lukewarm water; if your skin is dry, a rinse is enough.","optional":false},{"order":2,"product_type_slug":"serum-vitamin-c","note_el":"Λίγες σταγόνες για λάμψη και κηλίδες· οι δερματολόγοι τη θεωρούν κατάλληλη.","note_en":"A few drops for glow and dark spots; dermatologists consider it suitable.","optional":true},{"order":3,"product_type_slug":"serum-azelaic-acid","note_el":"Για σπυράκια ή κοκκινίλα, σε λεπτή στρώση· σταμάτα αν τσούζει επίμονα.","note_en":"For spots or redness, in a thin layer; stop if it keeps stinging.","optional":true},{"order":4,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Ενυδατική χωρίς άρωμα — το δέρμα στην εγκυμοσύνη ερεθίζεται πιο εύκολα.","note_en":"A fragrance-free moisturiser — skin reacts more easily in pregnancy.","optional":false},{"order":5,"product_type_slug":"sunscreen-tinted-iron-oxide","note_el":"Ορυκτά φίλτρα με χρώμα, SPF 30+, κάθε μέρα, μαζί με καπέλο και σκιά.","note_en":"Tinted mineral filters, SPF 30+, every day, together with a hat and shade.","optional":false}]'::jsonb, 5),
  ('f4132dba-51c9-f4a9-9802-5efa8bdea465'::uuid, 'face-women-all-pm-eu-melasma', 'face', 'Βραδινή ρουτίνα για μέλασμα και κηλίδες', 'Evening routine for melasma and dark spots', 'women', 'all', 'eu', 'pm', 'Το βράδυ δουλεύουν τα συστατικά που ομογενοποιούν τον τόνο, μέσα στα όρια που ορίζει η ΕΕ για τα καλλυντικά. Κανένα τρίψιμο, κανένα «σπιτικό peeling»: στο μέλασμα ο ερεθισμός κάνει τις κηλίδες πιο σκούρες. Ισχυρότερες θεραπείες, όπως η υδροκινόνη, είναι υπόθεση δερματολόγου.', 'At night the tone-evening ingredients do their work, within the EU’s cosmetic limits. No scrubbing, no “home peels”: with melasma, irritation makes the patches darker. Stronger treatments such as hydroquinone are a matter for a dermatologist.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Λιώνει το αντηλιακό με χρώμα και το μακιγιάζ χωρίς τρίψιμο.","note_en":"Melts tinted sunscreen and make-up without rubbing.","optional":true},{"order":2,"product_type_slug":"cleanser-cream-milk","note_el":"Δεύτερος, ήπιος καθαρισμός.","note_en":"A second, gentle cleanse.","optional":false},{"order":3,"product_type_slug":"serum-arbutin-kojic","note_el":"Σε όλο το πρόσωπο· κάνε πρώτα τεστ στο σαγόνι για μερικές μέρες.","note_en":"All over the face; patch test on the jawline for a few days first.","optional":false},{"order":4,"product_type_slug":"serum-azelaic-acid","note_el":"Εναλλακτικά με τον ορό λάμψης, σε διαφορετικά βράδια, αν το δέρμα το αντέχει.","note_en":"Alternate with the brightening serum on different nights, if your skin copes.","optional":true},{"order":5,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Κλείνει τη ρουτίνα και προστατεύει τον φραγμό.","note_en":"Closes the routine and protects the barrier.","optional":false}]'::jsonb, 6),
  ('6c4bdcda-9c10-a10b-6799-caf0ba9a4f12'::uuid, 'face-women-all-pm-eu-pregnancy-safe', 'face', 'Βραδινή ρουτίνα στην εγκυμοσύνη — χωρίς ρετινοειδή', 'Pregnancy evening routine — retinoid-free', 'women', 'all', 'eu', 'pm', 'Το βράδυ στην εγκυμοσύνη κρατάμε ό,τι είναι ήπιο και τεκμηριωμένο: αζελαϊκό οξύ για σπυράκια και κηλίδες, και αν θέλεις γλυκολικό μία με δύο φορές την εβδομάδα. Τα ρετινοειδή περιμένουν μέχρι να τελειώσει και ο θηλασμός.', 'In pregnancy the evening keeps what is gentle and well studied: azelaic acid for spots and marks, and glycolic acid once or twice a week if you like. Retinoids wait until breastfeeding is over too.', '[{"order":1,"product_type_slug":"cleanser-micellar-water","note_el":"Μόνο αν φοράς μακιγιάζ ή αντηλιακό με χρώμα, για να φύγει το πρώτο στρώμα.","note_en":"Only if you wear make-up or tinted sunscreen, to lift the first layer.","optional":true},{"order":2,"product_type_slug":"cleanser-cream-milk","note_el":"Ο κυρίως καθαρισμός, απαλά με τα δάχτυλα, χωρίς σφουγγάρι.","note_en":"The main cleanse, gently with your fingertips, no sponge.","optional":false},{"order":3,"product_type_slug":"serum-azelaic-acid","note_el":"Λεπτή στρώση σε στεγνό δέρμα, στα σημεία με σπυράκια ή κηλίδες.","note_en":"A thin layer on dry skin, over spots or dark patches.","optional":false},{"order":4,"product_type_slug":"exfoliant-aha-glycolic-lactic","note_el":"Μία ή δύο φορές την εβδομάδα, σε βράδυ χωρίς αζελαϊκό· όχι σε ερεθισμένο δέρμα.","note_en":"Once or twice a week, on a night without azelaic acid; not on irritated skin.","optional":true},{"order":5,"product_type_slug":"moisturizer-cream-ceramide","note_el":"Τελευταίο βήμα· βάλε και στον λαιμό και το ντεκολτέ.","note_en":"The last step; take it down to the neck and chest.","optional":false}]'::jsonb, 6),
  ('a17d0606-8adf-15f1-cc63-bfac2997a5c7'::uuid, 'face-women-combination-am-us-adult-acne', 'face', 'Πρωινή ρουτίνα για ακμή ενηλίκων', 'Morning routine for adult acne', 'women', 'combination', 'us', 'am', 'Η ακμή μετά τα 25 είναι συχνή στις γυναίκες, συνήθως στο σαγόνι και γύρω από το στόμα. Το πρωί θέλει ήπιο καθαρισμό, ένα ενεργό που δεν ξηραίνει και αντηλιακό που δεν φράζει τους πόρους. Αν τίποτα δεν βοηθά μετά από μερικούς μήνες, πήγαινε σε δερματολόγο.', 'Acne after 25 is common in women, usually on the jaw and around the mouth. The morning needs a gentle cleanse, an active that does not dry you out and a sunscreen that will not clog pores. If nothing helps after a few months, see a dermatologist.', '[{"order":1,"product_type_slug":"cleanser-gel-foaming","note_el":"Δύο φορές τη μέρα το πολύ· το συχνό πλύσιμο ερεθίζει.","note_en":"Twice a day at most; washing more often irritates.","optional":false},{"order":2,"product_type_slug":"serum-niacinamide","note_el":"Για λιπαρότητα και κοκκινίλα από τα σπυράκια.","note_en":"For oiliness and the redness left by spots.","optional":true},{"order":3,"product_type_slug":"serum-azelaic-acid","note_el":"Σε όλη τη ζώνη που βγάζει σπυράκια, όχι μόνο πάνω στο σπυράκι.","note_en":"Over the whole area that breaks out, not just on the spot.","optional":false},{"order":4,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Ελαφριά, με σήμα «μη φαγεσωρογόνο».","note_en":"Light, labelled non-comedogenic.","optional":false},{"order":5,"product_type_slug":"sunscreen-fluid-oil-control","note_el":"Ματ φινίρισμα που δεν βαραίνει και κρατάει κάτω από το μακιγιάζ.","note_en":"A matte finish that feels light and holds under make-up.","optional":false}]'::jsonb, 5),
  ('42202408-c985-fbc5-33e1-f7e15781674d'::uuid, 'face-women-combination-pm-us-adult-acne', 'face', 'Βραδινή ρουτίνα για ακμή ενηλίκων', 'Evening routine for adult acne', 'women', 'combination', 'us', 'pm', 'Το βράδυ είναι η ώρα του ρετινοειδούς: η αδαπαλένη χωρίς συνταγή κρατάει τους πόρους ανοιχτούς, αλλά θέλει τρεις μήνες για να φανεί. Όχι αν είσαι έγκυος ή προσπαθείς να μείνεις. Μακιγιάζ και αντηλιακό φεύγουν πάντα πριν τον ύπνο.', 'Evening is retinoid time: over-the-counter adapalene keeps pores clear, but takes three months to show. Not if you are pregnant or trying to be. Make-up and sunscreen always come off before bed.', '[{"order":1,"product_type_slug":"cleanser-micellar-water","note_el":"Αν φοράς μακιγιάζ, για να φύγει πριν τον κυρίως καθαρισμό.","note_en":"If you wear make-up, to lift it before the main cleanse.","optional":true},{"order":2,"product_type_slug":"cleanser-salicylic-wash","note_el":"Άφησέ το μισό λεπτό στο δέρμα και ξέπλυνε· σε μέρες ερεθισμού, ήπιο gel αντ’ αυτού.","note_en":"Leave it for half a minute, then rinse; on irritated days, a mild gel instead.","optional":false},{"order":3,"product_type_slug":"treatment-adapalene-otc","note_el":"Ένα μπιζέλι για όλο το πρόσωπο, σε στεγνό δέρμα, μέρα παρά μέρα στην αρχή.","note_en":"One pea for the whole face, on dry skin, every other night at first.","optional":false},{"order":4,"product_type_slug":"moisturizer-gel-oil-free","note_el":"Περίμενε λίγα λεπτά μετά το ρετινοειδές και βάλε την κρέμα.","note_en":"Wait a few minutes after the retinoid, then apply the cream.","optional":false},{"order":5,"product_type_slug":"treatment-hydrocolloid-patch","note_el":"Πάνω σε ανοιχτό σπυράκι, για να μην το πειράζεις τη νύχτα.","note_en":"Over an open spot, so you do not pick at it overnight.","optional":true}]'::jsonb, 6),
  ('b8bc9d84-ee17-fbad-f8dc-31ed7ac26076'::uuid, 'face-women-dry-am-eu-perimenopause', 'face', 'Πρωινή ρουτίνα για ώριμο δέρμα στην περιεμμηνόπαυση', 'Morning routine for mature skin in perimenopause', 'women', 'dry', 'eu', 'am', 'Με την πτώση των οιστρογόνων το δέρμα χάνει νερό και ελαστικότητα και γίνεται πιο λεπτό. Το πρωί δίνουμε ενυδάτωση σε στρώσεις και προστασία από τον ήλιο, που είναι η πιο αποδεδειγμένη αντιγηραντική κίνηση. Αν εμφανιστεί και ακμή, πες το στον δερματολόγο.', 'As oestrogen falls the skin loses water and elasticity and grows thinner. In the morning we layer hydration and add sun protection, the best-proven anti-ageing step. If breakouts appear as well, tell a dermatologist.', '[{"order":1,"product_type_slug":"cleanser-cream-milk","note_el":"Ή απλώς χλιαρό νερό, αν καθάρισες καλά το βράδυ.","note_en":"Or just lukewarm water, if you cleansed well the night before.","optional":true},{"order":2,"product_type_slug":"serum-vitamin-c","note_el":"Αντιοξειδωτική προστασία κάτω από το αντηλιακό.","note_en":"Antioxidant protection under the sunscreen.","optional":true},{"order":3,"product_type_slug":"serum-hyaluronic-acid","note_el":"Σε νωπό δέρμα, για να τραβήξει νερό.","note_en":"On damp skin, so it has water to draw in.","optional":false},{"order":4,"product_type_slug":"moisturizer-urea-face","note_el":"Μαλακώνει την τραχιά υφή· στις ξηρές περιοχές λίγο παραπάνω.","note_en":"Softens rough texture; a little extra on dry patches.","optional":false},{"order":5,"product_type_slug":"eye-cream-peptide","note_el":"Ελάχιστη ποσότητα, ταμπονάροντας.","note_en":"A tiny amount, tapped in.","optional":true},{"order":6,"product_type_slug":"sunscreen-eu-modern-filters","note_el":"SPF 30–50 με υψηλή UVA, σε πρόσωπο, λαιμό και ντεκολτέ.","note_en":"SPF 30–50 with high UVA, on face, neck and chest.","optional":false}]'::jsonb, 6),
  ('3eb55938-ec38-9438-581a-e75de63bc146'::uuid, 'face-women-dry-pm-eu-perimenopause', 'face', 'Βραδινή ρουτίνα για ώριμο δέρμα στην περιεμμηνόπαυση', 'Evening routine for mature skin in perimenopause', 'women', 'dry', 'eu', 'pm', 'Ένα ρετινοειδές και μια πλούσια κρέμα: αυτό είναι όλο. Η ρετινάλη ξεκινά δύο βράδια την εβδομάδα και ανεβαίνει μόνο αν το δέρμα δεν ερεθίζεται· τα άλλα βράδια μένει μόνο η κρέμα.', 'One retinoid and one rich cream: that is all. Retinal starts two nights a week and goes up only if the skin is not irritated; on the other nights it is just the cream.', '[{"order":1,"product_type_slug":"cleanser-oil-balm","note_el":"Λιώνει αντηλιακό και μακιγιάζ χωρίς να στεγνώνει το δέρμα· ξέπλυνε καλά.","note_en":"Melts sunscreen and make-up without drying the skin; rinse well.","optional":false},{"order":2,"product_type_slug":"serum-retinal","note_el":"Ένα μπιζέλι σε στεγνό δέρμα, μακριά από τα βλέφαρα και τις γωνίες της μύτης.","note_en":"One pea on dry skin, away from the eyelids and the corners of the nose.","optional":false},{"order":3,"product_type_slug":"moisturizer-rich-lipid-mature","note_el":"Γενναία ποσότητα, και στον λαιμό.","note_en":"A generous layer, down the neck too.","optional":false},{"order":4,"product_type_slug":"eye-cream-peptide","note_el":"Στο κόκαλο κάτω από το μάτι, όχι στο βλέφαρο.","note_en":"On the bone under the eye, not on the lid.","optional":true},{"order":5,"product_type_slug":"lip-ointment-repair","note_el":"Τα ρετινοειδή ξεραίνουν τα χείλη· λίγη αλοιφή πριν τον ύπνο.","note_en":"Retinoids dry the lips; a little ointment before bed.","optional":true}]'::jsonb, 5),
  ('215a2ba0-492f-f346-3fed-49478003468a'::uuid, 'nails-all-pm-daily-cuticle-care', 'nails', 'Καθημερινή φροντίδα επωνυχίων και νυχιών', 'Daily cuticle and nail care', 'all', 'all', 'global', 'pm', 'Δύο λεπτά πριν τον ύπνο για νύχια που σχίζονται και επωνύχια που σκάνε. Τα επωνύχια δεν κόβονται: προστατεύουν από τις λοιμώξεις, γι’ αυτό απλώς τα μαλακώνεις.', 'Two minutes before bed for nails that split and cuticles that crack. Cuticles are not cut: they protect against infection, so you simply soften them.', '[{"order":1,"product_type_slug":"cuticle-oil-jojoba","note_el":"Μία σταγόνα στη βάση κάθε νυχιού, με μασάζ.","note_en":"One drop at the base of each nail, massaged in.","optional":false},{"order":2,"product_type_slug":"nail-treatment-hydrating-serum","note_el":"Πάνω σε όλη την πλάκα και την άκρη.","note_en":"Over the whole plate and the free edge.","optional":true},{"order":3,"product_type_slug":"hand-cream-urea","note_el":"Τελευταία, για να κλείσει μέσα την υγρασία.","note_en":"Last, to seal the moisture in.","optional":false}]'::jsonb, 2),
  ('df827f29-1a9c-4f22-d6d2-fb1ba5cb5f6a'::uuid, 'nails-women-pm-gel-soak-off-removal', 'nails', 'Ασφαλής αφαίρεση ημιμόνιμου στο σπίτι', 'Removing gel polish safely at home', 'women', 'all', 'global', 'pm', 'Το ημιμόνιμο που ξεκολλάει με τα νύχια παίρνει μαζί του στρώσεις από την πλάκα. Μουλιάζεις, περιμένεις, σπρώχνεις απαλά — και μετά δίνεις στο νύχι λάδι και ενυδάτωση. Αν έχεις αλλεργία στην ασετόνη, προτίμησε κλασικό βερνίκι.', 'Gel polish peeled off with your nails takes layers of the plate with it. Soak, wait, nudge gently — then give the nail oil and moisture. If you are allergic to acetone, stick to regular polish.', '[{"order":1,"product_type_slug":"nail-remover-gel-soak-off","note_el":"Βαμβάκι με ασετόνη και αλουμινόχαρτο για 10–15 λεπτά· όχι κοντά σε φλόγα.","note_en":"Acetone-soaked cotton under foil for 10–15 minutes; away from any flame.","optional":false},{"order":2,"product_type_slug":"nail-file-glass","note_el":"Μόνο για να στρώσεις την άκρη, προς μία κατεύθυνση, όχι πάνω στην πλάκα.","note_en":"Only to tidy the free edge, in one direction, never over the plate.","optional":true},{"order":3,"product_type_slug":"cuticle-oil-jojoba","note_el":"Μία σταγόνα σε κάθε νύχι αμέσως μετά — η ασετόνη έχει στεγνώσει τα πάντα.","note_en":"One drop per nail straight after — the acetone has dried everything out.","optional":false},{"order":4,"product_type_slug":"nail-treatment-hydrating-serum","note_el":"Κάθε βράδυ για τις επόμενες εβδομάδες, πριν το επόμενο χρώμα.","note_en":"Every night for the next weeks, before the next colour.","optional":true},{"order":5,"product_type_slug":"hand-cream-urea","note_el":"Στα χέρια και πάνω στα νύχια.","note_en":"On the hands and over the nails.","optional":false}]'::jsonb, 25),
  ('af864118-b3b1-1976-b149-c93e8f406e25'::uuid, 'nails-women-weekly-natural-nail-break', 'nails', 'Εβδομάδα «ξεκούρασης» από το ημιμόνιμο', 'A week off gel: natural-nail care', 'women', 'all', 'global', 'weekly', 'Οι δερματολόγοι προτείνουν να κρατάς τα τεχνητά νύχια και το ημιμόνιμο για ειδικές περιστάσεις, ώστε τα φυσικά νύχια να συνέρχονται. Μια φορά την εβδομάδα: σχήμα, βάση που λειαίνει, λάδι — και αντηλιακό στα χέρια κάθε πρωί.', 'Dermatologists suggest saving artificial nails and gel for special occasions, so natural nails can recover. Once a week: shape, a smoothing base coat, oil — and sunscreen on the hands every morning.', '[{"order":1,"product_type_slug":"nail-remover-acetone-free","note_el":"Αν υπάρχει παλιό βερνίκι, με ένα πέρασμα, χωρίς τρίψιμο.","note_en":"If there is old polish, in one sweep, without rubbing.","optional":true},{"order":2,"product_type_slug":"nail-file-glass","note_el":"Κοντό, στρογγυλεμένο σχήμα, σε στεγνά νύχια, προς μία κατεύθυνση.","note_en":"A short, rounded shape, on dry nails, in one direction.","optional":false},{"order":3,"product_type_slug":"base-coat-ridge-filler","note_el":"Μία στρώση για λείο, περιποιημένο φινίρισμα χωρίς χρώμα.","note_en":"One coat for a smooth, groomed, colour-free finish.","optional":true},{"order":4,"product_type_slug":"cuticle-oil-jojoba","note_el":"Και κάθε βράδυ της εβδομάδας.","note_en":"And every night of the week.","optional":false},{"order":5,"product_type_slug":"hand-cream-spf","note_el":"Κάθε πρωί, και ξανά μετά το πλύσιμο των χεριών.","note_en":"Every morning, and again after washing your hands.","optional":false}]'::jsonb, 15)
insert into hygieia.skincare_tips (id, slug, area, title_el, title_en, body_el, body_en, audiences, skin_types, concerns, regions, sources, needs_source) values
  ('1c8a26cc-3bad-4e79-faa1-4a6a1d23507d'::uuid, 'face-all-azelaic-acid-for-redness-spots-and-marks', 'face', 'Αζελαϊκό οξύ: ένα συστατικό για κοκκινίλα, σπυράκια και κηλίδες', 'Azelaic acid: one ingredient for redness, spots and marks', 'Μια συστηματική ανασκόπηση βρήκε ότι το αζελαϊκό οξύ βοηθά στην ακμή, στην κοκκινίλα της ροδόχρου και στο μέλασμα, με ήπιο και παροδικό τσούξιμο ως συνηθέστερη παρενέργεια. Τα καλλυντικά στην αγορά έχουν συνήθως έως 10 %, ενώ οι πιο ισχυρές μορφές δίνονται με συνταγή. Για ροδόχρου ή μέλασμα, ζήτα τη γνώμη δερματολόγου για τη σωστή μορφή.', 'A systematic review found that azelaic acid helps acne, rosacea redness and melasma, with mild, short-lived stinging as the most common side effect. Cosmetics usually contain up to 10 %, while stronger forms are prescribed. For rosacea or melasma, ask a dermatologist about the right form.', array['all']::text[], array['all','sensitive']::text[], array['redness','acne','pigmentation']::text[], array['global']::text[], array['https://pubmed.ncbi.nlm.nih.gov/37550898/','https://www.aad.org/public/diseases/a-z/melasma-treatment']::text[], false),
  ('153e45dd-6c12-3334-532c-f67692892eea'::uuid, 'face-all-bakuchiol-what-the-evidence-says', 'face', 'Μπακουχιόλη: τι λένε πραγματικά οι μελέτες', 'Bakuchiol: what the studies actually say', 'Σε μια μικρή τυχαιοποιημένη μελέτη 12 εβδομάδων, η μπακουχιόλη 0,5 % δύο φορές τη μέρα βελτίωσε τις ρυτίδες και τις κηλίδες περίπου όσο η ρετινόλη 0,5 %, με λιγότερο ξεφλούδισμα και τσούξιμο. Οι μελέτες είναι ακόμη λίγες, άρα είναι μια λογική εναλλακτική για όποιον δεν αντέχει τη ρετινόλη, όχι μια αποδεδειγμένα ισότιμη αντικατάσταση. Όπως με κάθε νέο προϊόν, κάνε πρώτα τεστ.', 'In a small 12-week randomised trial, 0.5 % bakuchiol twice a day improved wrinkles and dark spots about as much as 0.5 % retinol, with less peeling and stinging. The studies are still few, so it is a reasonable alternative for anyone who cannot tolerate retinol, not a proven equal replacement. As with any new product, patch test first.', array['all']::text[], array['sensitive','all']::text[], array['aging','pigmentation']::text[], array['global']::text[], array['https://pubmed.ncbi.nlm.nih.gov/29947134/','https://pubmed.ncbi.nlm.nih.gov/36176207/']::text[], false),
  ('adc59a0d-e85c-af48-88ef-816e8297b3ec'::uuid, 'face-all-benzoyl-peroxide-bleaches-fabric', 'face', 'Υπεροξείδιο του βενζοϋλίου: προσοχή στις πετσέτες και τα μαξιλάρια', 'Benzoyl peroxide: mind your towels and pillowcases', 'Το υπεροξείδιο του βενζοϋλίου είναι από τα πιο τεκμηριωμένα για την ακμή, αλλά ξεβάφει πετσέτες, μαξιλαροθήκες, ρούχα και μαλλιά. Χρησιμοποίησε λευκές πετσέτες, άφησέ το να στεγνώσει πριν ακουμπήσεις υφάσματα και ξεκίνα με χαμηλή συγκέντρωση. Κάνει το δέρμα πιο ευαίσθητο στον ήλιο, οπότε αντηλιακό κάθε πρωί.', 'Benzoyl peroxide is one of the best-studied acne treatments, but it bleaches towels, pillowcases, clothes and hair. Use white towels, let it dry before it touches fabric and start with a low strength. It makes the skin more sensitive to the sun, so wear sunscreen every morning.', array['all']::text[], array['oily','combination']::text[], array['acne']::text[], array['global']::text[], array['https://www.nhs.uk/medicines/benzoyl-peroxide/']::text[], false),
  ('1ad80252-81b5-c553-ca4a-0d3b213e2069'::uuid, 'face-all-darker-skin-exfoliate-gently', 'face', 'Σκουρόχρωμη επιδερμίδα: ήπια απολέπιση, για να μη μείνουν κηλίδες', 'Darker skin: exfoliate gently, so no dark marks are left', 'Σε πιο σκούρο δέρμα, μια επιθετική απολέπιση μπορεί να αφήσει σκούρες κηλίδες εκεί που ήθελες λάμψη. Διάλεξε ήπιο απολεπιστικό και κράτα το σε μία ή δύο φορές την εβδομάδα. Αν το δέρμα κοκκινίσει ή τσούξει, σταμάτα, και πριν από peeling ή laser μίλησε με δερματολόγο.', 'On darker skin, aggressive exfoliation can leave dark marks where you wanted a glow. Choose a gentle exfoliant and keep it to once or twice a week. If the skin reddens or stings, stop, and before any peel or laser talk to a dermatologist.', array['all']::text[], array['all']::text[], array['texture','pigmentation']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home','https://www.aad.org/public/everyday-care/skin-care-secrets/routine/fade-dark-spots']::text[], false),
  ('4f0a030c-aaa9-9105-dde1-7fd96bb0efd8'::uuid, 'face-all-emollient-smooth-it-on-do-not-rub', 'face', 'Μαλακτική κρέμα: απλώνεται απαλά, με τη φορά της τρίχας', 'Emollients: smooth them on, in the direction of hair growth', 'Μια πλούσια μαλακτική κρέμα δουλεύει καλύτερα αμέσως μετά το πλύσιμο, όταν έχεις ταμπονάρει το δέρμα. Άπλωσέ την απαλά προς την κατεύθυνση που φυτρώνουν οι τρίχες, χωρίς τρίψιμο, για να μη φράξουν οι θύλακοι. Μακριά από φλόγες και τσιγάρα: τα υφάσματα που έχουν απορροφήσει κρέμα πιάνουν φωτιά πιο εύκολα.', 'A rich emollient works best straight after washing, once you have patted the skin dry. Smooth it on gently in the direction the hair grows, without rubbing, so follicles do not get blocked. Keep away from flames and cigarettes: fabrics that have soaked up cream catch fire more easily.', array['all']::text[], array['dry','sensitive']::text[], array['hydration']::text[], array['global']::text[], array['https://www.nhs.uk/tests-and-treatments/emollients/','https://www.aad.org/public/everyday-care/skin-care-basics/dry/dermatologists-tips-relieve-dry-skin']::text[], false),
  ('f75c8401-081d-008d-f280-bb57cea61cd8'::uuid, 'face-all-eu-limits-on-brightening-actives', 'face', 'Λευκαντικά συστατικά στην ΕΕ: όρια για άλφα-αρμπουτίνη και κογικό οξύ', 'Brightening actives in the EU: limits for alpha-arbutin and kojic acid', 'Από το 2025 η ΕΕ επιτρέπει έως 2 % άλφα-αρμπουτίνη και 7 % αρμπουτίνη σε κρέμες προσώπου, και έως 1 % κογικό οξύ σε προϊόντα προσώπου και χεριών. Προϊόντα από το διαδίκτυο ή από χώρες εκτός ΕΕ μπορεί να μην τηρούν αυτά τα όρια ή να περιέχουν απαγορευμένες ουσίες. Αγόραζε από φαρμακεία και καταστήματα με ετικέτα στα ελληνικά και πλήρη λίστα συστατικών.', 'Since 2025 the EU allows up to 2 % alpha-arbutin and 7 % arbutin in face creams, and up to 1 % kojic acid in face and hand products. Products from the internet or from outside the EU may not respect these limits or may contain banned substances. Buy from pharmacies and shops with a label in your language and a full ingredient list.', array['all','women']::text[], array['all']::text[], array['pigmentation']::text[], array['eu']::text[], array['https://eur-lex.europa.eu/eli/reg/2024/996/oj','https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32009R1223']::text[], false),
  ('c6fdca06-6021-d1f2-51ac-e5120b02e8a1'::uuid, 'face-all-eu-retinol-cap-0-3-percent', 'face', 'Ρετινόλη στην ΕΕ: έως 0,3 % RE στα καλλυντικά, 0,05 % στις λοσιόν σώματος', 'Retinol in the EU: up to 0.3 % RE in cosmetics, 0.05 % in body lotions', 'Ο Κανονισμός (ΕΕ) 2024/996 βάζει όριο 0,05 % σε ισοδύναμα ρετινόλης (RE) για τη ρετινόλη και τους εστέρες της στις λοσιόν σώματος, και 0,3 % RE σε όλα τα άλλα καλλυντικά που παραμένουν ή ξεβγάζονται. Προϊόντα εκτός ορίων δεν μπαίνουν στην αγορά από τον Νοέμβριο του 2025 και πρέπει να έχουν αποσυρθεί ως τον Μάιο του 2027. Περισσότερη ρετινόλη δεν σημαίνει καλύτερο αποτέλεσμα, μόνο περισσότερο ερεθισμό· ισχυρότερα ρετινοειδή δίνει ο δερματολόγος με συνταγή.', 'Regulation (EU) 2024/996 caps retinol and its esters at 0.05 % retinol equivalent (RE) in body lotions and 0.3 % RE in other leave-on and rinse-off cosmetics. Non-compliant products cannot be placed on the market from November 2025 and must be off the shelves by May 2027. More retinol does not mean better results, only more irritation. Stronger retinoids come from a dermatologist on prescription.', array['all']::text[], array['all']::text[], array['aging']::text[], array['eu']::text[], array['https://eur-lex.europa.eu/eli/reg/2024/996/oj','https://www.aad.org/public/everyday-care/skin-care-secrets/anti-aging/retinoid-retinol']::text[], false),
  ('76359215-1857-6f66-54fc-0e8d79f5bd92'::uuid, 'face-all-greek-summer-sunscreen-in-the-bag', 'face', 'Ελληνικό καλοκαίρι: το αντηλιακό μένει στην τσάντα, όχι στο σπίτι', 'Greek summer: the sunscreen lives in your bag, not at home', 'Ένα πρωινό στρώμα δεν φτάνει για μια μέρα στην παραλία, στο νησί ή στη βόλτα στο κέντρο. Κράτα ένα μικρό αντηλιακό ή ένα στικ στην τσάντα και ανανέωνε κάθε δύο ώρες έξω, και πάντα μετά τη θάλασσα. Όταν ο δείκτης UV είναι υψηλός (3+), προτίμησε τη σκιά, ειδικά γύρω στο μεσημέρι.', 'One morning layer is not enough for a day at the beach, on an island or walking around town. Keep a small sunscreen or a stick in your bag and reapply every two hours outdoors, and always after the sea. When the UV index is high (3+), seek shade, especially around midday.', array['all']::text[], array['all']::text[], array['sun']::text[], array['eu','global']::text[], array['https://www.nhs.uk/live-well/seasonal-health/sunscreen-and-sun-safety/','https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen']::text[], false),
  ('fee5cc10-3695-0ea6-94ab-35174a7a2feb'::uuid, 'face-all-heat-rash-keep-cool', 'face', 'Ιδρωτοφουσκάλες το καλοκαίρι: δροσιά και ελαφριά ρούχα', 'Heat rash in summer: keep cool, wear loose clothes', 'Τα μικρά κόκκινα σπυράκια που τσιμπάνε στη ζέστη και την υγρασία είναι συνήθως ιδρωτοφουσκάλες. Φόρα φαρδιά βαμβακερά ρούχα, κάνε δροσερά ντους, πίνε νερό και απόφυγε αφρόλουτρα και κρέμες με άρωμα. Μην ξύνεις, και αν δεν βελτιωθεί σε λίγες μέρες ρώτα φαρμακοποιό ή γιατρό.', 'Small, prickly red spots in heat and humidity are usually heat rash. Wear loose cotton clothes, take cool showers, drink water and avoid perfumed shower gels and creams. Do not scratch, and if it does not improve in a few days, ask a pharmacist or doctor.', array['all']::text[], array['all']::text[], array['redness','sun']::text[], array['eu','global']::text[], array['https://www.nhs.uk/conditions/heat-rash-prickly-heat/']::text[], false),
  ('cae578a7-ff1d-a597-26d1-33a3c525c407'::uuid, 'face-all-new-product-rash-stop-it', 'face', 'Κοκκινίλα και φαγούρα μετά από νέο προϊόν: σταμάτα το', 'Redness and itching after a new product: stop using it', 'Ένα εξάνθημα με φαγούρα, κάψιμο ή ξηρότητα λίγες ώρες ή μέρες μετά από ένα νέο καλλυντικό μπορεί να είναι δερματίτιδα εξ επαφής, συχνά από άρωμα ή συντηρητικά. Σταμάτα το προϊόν, πλύνε απαλά και βάλε μια απλή, μαλακτική κρέμα χωρίς άρωμα. Αν δεν βελτιωθεί σε λίγες μέρες ή απλώνεται, πήγαινε σε γιατρό ή φαρμακοποιό.', 'An itchy, burning or dry rash a few hours or days after a new cosmetic may be contact dermatitis, often from fragrance or preservatives. Stop the product, wash gently and apply a plain, fragrance-free emollient. If it does not improve within a few days or keeps spreading, see a doctor or pharmacist.', array['all']::text[], array['sensitive','all']::text[], array['redness']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/contact-dermatitis/']::text[], false),
  ('9a929bb7-a931-1d04-6ab6-d530f8e1879c'::uuid, 'face-all-price-is-not-quality', 'face', 'Η ακριβή κρέμα δεν είναι απαραίτητα καλύτερη', 'An expensive cream is not necessarily a better one', 'Αποτελεσματικά προϊόντα περιποίησης υπάρχουν σε κάθε κατηγορία τιμής. Το «κλινικά αποδεδειγμένο» σημαίνει συνήθως ότι το δοκίμασαν καταναλωτές, όχι ότι το ενέκρινε κάποια αρχή. Αντηλιακό, ήπιο καθαριστικό και ενυδατική από το φαρμακείο ή το σούπερ μάρκετ κάνουν τη μεγαλύτερη διαφορά.', 'Effective skin care products exist at every price point. “Clinically proven” usually means consumers tried it, not that any authority approved it. Sunscreen, a mild cleanser and a moisturiser from the pharmacy or supermarket make the biggest difference.', array['all']::text[], array['all']::text[], array['general']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/anti-aging/selecting-anti-aging-products']::text[], false),
  ('b707d222-73fb-ac91-1b99-c630f57dae14'::uuid, 'face-all-rosacea-greek-summer-triggers', 'face', 'Ροδόχρου το ελληνικό καλοκαίρι: ζέστη, καυτά ροφήματα, αλκοόλ', 'Rosacea in a Greek summer: heat, hot drinks, alcohol', 'Η ζέστη, ο ήλιος, τα καυτά ροφήματα, το αλκοόλ, τα πικάντικα φαγητά και η έντονη άσκηση είναι συχνοί πυροδότες της ροδόχρου. Το καλοκαίρι, κάνε σκιά, πίνε τον καφέ σου κρύο, γυμνάσου νωρίς το πρωί και δρόσιζε το πρόσωπο με δροσερό, όχι παγωμένο, νερό. Κράτα ημερολόγιο για να βρεις τους δικούς σου πυροδότες και δείξ’ το στον δερματολόγο.', 'Heat, sun, hot drinks, alcohol, spicy food and strenuous exercise are common rosacea triggers. In summer, stay in the shade, have your coffee iced, exercise early in the morning and cool your face with cool, not icy, water. Keep a diary to find your own triggers and show it to your dermatologist.', array['all']::text[], array['sensitive']::text[], array['redness']::text[], array['eu','global']::text[], array['https://www.aad.org/public/diseases/rosacea/triggers/prevent','https://www.nhs.uk/conditions/rosacea/','https://www.aad.org/public/diseases/rosacea/insider/things-to-know']::text[], false),
  ('0a527ece-d306-7a1e-6535-e01de15a360a'::uuid, 'face-all-rosacea-ingredients-to-skip', 'face', 'Ροδόχρου: τα συστατικά που καλό είναι να αποφεύγεις', 'Rosacea: the ingredients best avoided', 'Σε δέρμα με ροδόχρου οι δερματολόγοι προτείνουν να αποφεύγεις οινόπνευμα, καμφορά, άρωμα, γλυκολικό και γαλακτικό οξύ, μενθόλη, sodium lauryl sulfate και ουρία. Προτίμησε προϊόντα χωρίς άρωμα, για ευαίσθητη επιδερμίδα, και κρέμες αντί για τόνερ και στυπτικά. Η διάγνωση και η θεραπεία της ροδόχρου είναι δουλειά του δερματολόγου.', 'For rosacea-prone skin, dermatologists suggest avoiding alcohol, camphor, fragrance, glycolic and lactic acid, menthol, sodium lauryl sulfate and urea. Prefer fragrance-free products made for sensitive skin, and creams over toners and astringents. Diagnosing and treating rosacea is a dermatologist’s job.', array['all']::text[], array['sensitive']::text[], array['redness']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/rosacea/triggers/tips']::text[], false),
  ('49c64947-e25d-2722-08e3-50fa38f6e314'::uuid, 'face-all-rosacea-mineral-sunscreen-every-day', 'face', 'Ροδόχρου και ήλιος: ορυκτό αντηλιακό κάθε μέρα', 'Rosacea and sun: a mineral sunscreen every day', 'Ο ήλιος είναι από τις πιο συχνές αιτίες έξαρσης της ροδόχρου. Οι δερματολόγοι προτείνουν αντηλιακό SPF 30+ με οξείδιο του ψευδαργύρου ή διοξείδιο του τιτανίου, που συνήθως ενοχλεί λιγότερο το ευαίσθητο δέρμα, μαζί με σκιά και καπέλο. Ένα κονσίλερ με πράσινη απόχρωση καμουφλάρει την κοκκινίλα, αν θέλεις.', 'Sun is one of the most common rosacea flare triggers. Dermatologists suggest an SPF 30+ sunscreen with zinc oxide or titanium dioxide, which usually bothers sensitive skin less, plus shade and a hat. A green-tinted concealer can camouflage the redness if you wish.', array['all']::text[], array['sensitive']::text[], array['redness','sun']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/rosacea/triggers/tips','https://www.aad.org/public/diseases/rosacea/triggers/prevent']::text[], false),
  ('791d69fc-b743-a869-03b9-42469da5fa18'::uuid, 'face-all-rosacea-test-new-products-for-a-week', 'face', 'Ροδόχρου: δοκίμασε κάθε νέο προϊόν στο μπράτσο για μία εβδομάδα', 'Rosacea: test each new product on your arm for a week', 'Πριν βάλεις ένα νέο προϊόν στο πρόσωπο, άπλωσε λίγο στο εσωτερικό του μπράτσου κάθε μέρα για 7–10 μέρες. Αν δεν κοκκινίσει, δεν τσούξει και δεν πρηστεί, δοκίμασέ το σε μια μικρή περιοχή του προσώπου. Ένα νέο προϊόν τη φορά, ώστε να ξέρεις ποιο φταίει αν το δέρμα αντιδράσει, και ρώτα τον δερματολόγο σου αν η ροδόχρου επιμένει.', 'Before a new product goes on your face, spread a little on the inside of your arm every day for 7–10 days. If it does not redden, sting or swell, try it on a small area of the face. One new product at a time, so you know which is to blame if your skin reacts, and ask your dermatologist if the rosacea persists.', array['all']::text[], array['sensitive']::text[], array['redness']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/rosacea/triggers/tips']::text[], false),
  ('c4600d9e-7d7c-52a0-a137-5d3104c1496b'::uuid, 'face-all-spray-sunscreen-into-your-hands-for-the-face', 'face', 'Αντηλιακό σπρέι: για το πρόσωπο, πρώτα στις παλάμες', 'Spray sunscreen: for the face, into your palms first', 'Μην ψεκάζεις αντηλιακό κατευθείαν στο πρόσωπο, για να μην το εισπνεύσεις και να μην πάει στα μάτια. Ψέκασε στις παλάμες και άπλωσε. Στο σώμα, ψέκασε μέχρι να γυαλίσει το δέρμα και άπλωσε με το χέρι, γιατί ο αέρας παίρνει μεγάλο μέρος.', 'Do not spray sunscreen straight at your face, so you do not breathe it in or get it in your eyes. Spray it into your palms and spread it on. On the body, spray until the skin glistens and rub it in, because the wind carries a lot away.', array['all']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen','https://www.fda.gov/consumers/consumer-updates/tips-stay-safe-sun-sunscreen-sunglasses']::text[], false),
  ('cebde472-c43a-d45d-66ed-3620211d2abb'::uuid, 'face-all-sunburn-cool-moisturise-drink', 'face', 'Κάηκες; Δροσιά, ενυδατική χωρίς άρωμα και νερό', 'Sunburnt? Cool water, unperfumed moisturiser, plenty to drink', 'Βγες από τον ήλιο και δρόσισε το δέρμα με δροσερό ντους ή υγρή πετσέτα — όχι με πάγο. Βάλε gel για μετά τον ήλιο ή ενυδατική χωρίς άρωμα όσο το δέρμα είναι νωπό, πιες άφθονο νερό και απόφυγε το αλκοόλ. Κράτα την καμένη περιοχή καλυμμένη από τον ήλιο μέχρι να επουλωθεί.', 'Get out of the sun and cool the skin with a cool shower or a damp towel — not ice. Apply after-sun gel or an unperfumed moisturiser while the skin is damp, drink plenty of water and avoid alcohol. Keep the burnt area covered from the sun until it has healed.', array['all']::text[], array['all']::text[], array['sun','redness']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/sunburn/','https://www.aad.org/public/everyday-care/injured-skin/burns/treat-sunburn']::text[], false),
  ('c2a736cc-be73-0f5d-8f08-a8d82fad8456'::uuid, 'face-all-sunburn-do-not-pop-blisters', 'face', 'Έγκαυμα από τον ήλιο: μη σπας φουσκάλες, μην ξεφλουδίζεις', 'Sunburn: do not pop blisters or peel the skin', 'Οι φουσκάλες σημαίνουν πιο βαθύ έγκαυμα και προστατεύουν το δέρμα από τις λοιμώξεις, γι’ αυτό δεν τις σπάμε. Μην ξύνεις και μην τραβάς το δέρμα που ξεφλουδίζει, και απόφυγε προϊόντα με αναισθητικά «-καΐνη», που ερεθίζουν. Μέχρι να επουλωθεί, άφησε στην άκρη οξέα και ρετινοειδή.', 'Blisters mean a deeper burn and protect the skin from infection, so do not pop them. Do not scratch or pull at peeling skin, and avoid “-caine” numbing products, which can irritate. Until it heals, put acids and retinoids aside.', array['all']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/injured-skin/burns/treat-sunburn','https://www.nhs.uk/conditions/sunburn/']::text[], false),
  ('ada285cf-5109-7526-62de-c5b84b7455ad'::uuid, 'face-all-sunburn-when-to-get-help', 'face', 'Πότε ένα έγκαυμα από τον ήλιο θέλει γιατρό', 'When sunburn needs a doctor', 'Ζήτα βοήθεια αν το δέρμα έχει φουσκάλες σε μεγάλη έκταση ή πρήζεται, αν έχεις πυρετό, ρίγη, ζάλη, πονοκέφαλο, ναυτία ή κράμπες. Αυτά μπορεί να σημαίνουν θερμική εξάντληση ή θερμοπληξία, που είναι σοβαρές καταστάσεις. Τα μωρά και τα μικρά παιδιά με έγκαυμα τα βλέπει πάντα γιατρός.', 'Get help if the skin is widely blistered or swollen, or if you have a fever, chills, dizziness, a headache, nausea or cramps. These can mean heat exhaustion or heatstroke, which are serious. Babies and young children with sunburn should always be seen by a doctor.', array['all']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/sunburn/','https://www.aad.org/public/everyday-care/injured-skin/burns/treat-sunburn']::text[], false),
  ('b1e49456-14a8-b01c-0d15-bc663b9daca2'::uuid, 'face-all-water-resistant-is-not-waterproof', 'face', 'Αντηλιακό «ανθεκτικό στο νερό» δεν σημαίνει ότι δεν φεύγει', '“Water-resistant” sunscreen still comes off', 'Στην ΕΕ η σύσταση για τις ετικέτες λέει ότι κανένα αντηλιακό δεν δίνει «πλήρη» προστασία, οπότε όροι όπως «sunblock» ή «100 % προστασία» δεν πρέπει να εμφανίζονται. Στις ΗΠΑ το «ανθεκτικό στο νερό» (water resistant) σημαίνει ότι κρατάει 40 ή 80 λεπτά στο νερό. Μετά το κολύμπι, τον ιδρώτα ή το σκούπισμα με πετσέτα, ξαναβάζεις.', 'In the EU, the labelling recommendation says no sunscreen gives “total” protection, so terms like “sunblock” or “100 % protection” should not appear. In the US, “water resistant” means it lasts 40 or 80 minutes in water. After swimming, sweating or towelling off, put it on again.', array['all']::text[], array['all']::text[], array['sun']::text[], array['eu','us']::text[], array['https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32006H0647','https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun']::text[], false),
  ('576e8e7d-8a66-4df5-6729-c007a2d3c8f4'::uuid, 'face-men-fewer-blades-for-razor-bumps', 'face', 'Σπυράκια από το ξύρισμα; Δοκίμασε ξυράφι με μία ή δύο λεπίδες', 'Razor bumps? Try a single- or double-blade razor', 'Τα ξυράφια με πολλές λεπίδες κόβουν την τρίχα πιο κοντά, κάτω από την επιφάνεια, και αυτό ευνοεί τις τρίχες που μπαίνουν μέσα. Αν βγάζεις σπυράκια ή κάψιμο, οι δερματολόγοι προτείνουν ξυράφι με μία ή δύο λεπίδες, βρεγμένο δέρμα, ενυδατικό αφρό και ξύρισμα με τη φορά της τρίχας. Άλλαζε λεπίδα κάθε πέντε με επτά ξυρίσματα.', 'Multi-blade razors cut the hair closer, below the surface, which encourages ingrown hairs. If you get bumps or burn, dermatologists suggest a single- or double-blade razor, wet skin, a moisturising shaving cream and shaving with the grain. Change the blade every five to seven shaves.', array['men']::text[], array['all']::text[], array['shaving','redness']::text[], array['global']::text[], array['https://www.aad.org/skin-care-basics/skin-care-for-men']::text[], false),
  ('be3c6a61-d356-59a1-fe80-4af642ce9d80'::uuid, 'face-men-mild-cleanser-not-bar-soap', 'face', 'Για άντρες: ήπιο καθαριστικό προσώπου, όχι το σαπούνι του μπάνιου', 'For men: a mild face cleanser, not the bathroom soap', 'Οι δερματολόγοι προτείνουν πλύσιμο κάθε μέρα και μετά την προπόνηση με ήπιο καθαριστικό προσώπου και χλιαρό νερό, όχι με κλασικό σαπούνι. Αν το δέρμα σου βγάζει σπυράκια, διάλεξε προϊόντα «oil-free» ή «μη φαγεσωρογόνα», κι αν είναι ευαίσθητο, «χωρίς άρωμα». Η ενυδατική μπαίνει όσο το δέρμα είναι ακόμα νωπό.', 'Dermatologists suggest washing daily and after exercise with a mild face cleanser and lukewarm water, not ordinary bar soap. If your skin breaks out, pick oil-free or non-comedogenic products, and if it is sensitive, fragrance-free ones. Moisturiser goes on while the skin is still damp.', array['men']::text[], array['all']::text[], array['general','acne']::text[], array['global']::text[], array['https://www.aad.org/skin-care-basics/skin-care-for-men']::text[], false),
  ('841cee42-5a23-d0c0-4849-580d96bb095e'::uuid, 'face-men-sunscreen-ears-neck-and-scalp', 'face', 'Αντηλιακό και στα αυτιά, τον σβέρκο και το κεφάλι', 'Sunscreen on the ears, the back of the neck and the scalp', 'Τα αυτιά, ο σβέρκος και, σε όσους αραιώνουν τα μαλλιά, το κεφάλι είναι σημεία που καίγονται εύκολα και ξεχνιούνται. Βάλε εκεί αντηλιακό SPF 30+ ανθεκτικό στο νερό και ανανέωνε κάθε δύο ώρες έξω. Ένα καπέλο με φαρδύ γείσο καλύπτει ό,τι δεν φτάνει το χέρι.', 'The ears, the back of the neck and, for men with thinning hair, the scalp burn easily and are often forgotten. Put water-resistant SPF 30+ there and reapply every two hours outdoors. A wide-brimmed hat covers what your hand cannot reach.', array['men','all']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen','https://www.aad.org/skin-care-basics/skin-care-for-men']::text[], false),
  ('f1d6b936-67ca-c1c4-036b-47c544470078'::uuid, 'face-women-acne-marks-fade-slowly', 'face', 'Τα σκούρα σημάδια της ακμής φεύγουν αργά — μην τα πειράζεις', 'Dark acne marks fade slowly — leave them alone', 'Τα καφέ ή μωβ σημάδια που αφήνει ένα σπυράκι, ιδίως σε πιο σκούρο δέρμα, ξεθωριάζουν σε μήνες και σκουραίνουν με τον ήλιο. Μην σπας και μην ξύνεις τα σπυράκια, γιατί έτσι τα σημάδια γίνονται πιο έντονα. Αντηλιακό με χρώμα κάθε μέρα και ένα προϊόν όπως ρετινόλη ή αζελαϊκό οξύ βοηθούν· βαθιές ουλές θέλουν δερματολόγο.', 'The brown or purple marks a spot leaves, especially on darker skin, fade over months and darken in the sun. Do not squeeze or pick spots, because that makes the marks stronger. Daily tinted sunscreen and a product such as retinol or azelaic acid help; deep scars need a dermatologist.', array['women','all']::text[], array['all']::text[], array['acne','pigmentation']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/routine/fade-dark-spots','https://www.aad.org/public/diseases/acne/diy/skin-color','https://www.aad.org/public/diseases/acne/derm-treat/scars']::text[], false),
  ('a0014901-2301-6ca4-65d8-1364a5fae92d'::uuid, 'face-women-adult-acne-check-labels', 'face', 'Ακμή ενηλίκων: διάβασε την ετικέτα κάθε κρέμας και make-up', 'Adult acne: read the label on every cream and make-up', 'Ενυδατικές, αντηλιακά, καλλυντικά μακιγιάζ και προϊόντα μαλλιών μπορούν να φράξουν τους πόρους. Διάλεξε όσα γράφουν «μη φαγεσωρογόνο» (non-comedogenic) ή «χωρίς λιπαρά» (oil-free). Ξεβάφεσαι πάντα πριν τον ύπνο και καθαρίζεις τα πινέλα τακτικά.', 'Moisturisers, sunscreens, make-up and hair products can all clog pores. Choose the ones labelled non-comedogenic or oil-free. Always take make-up off before bed and clean your brushes regularly.', array['women']::text[], array['oily','combination']::text[], array['acne','pores']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/acne/really-acne/adult-acne','https://www.aad.org/public/diseases/acne/causes/makeup']::text[], false),
  ('d836c48e-f266-3d48-0b1e-1e059cc561a0'::uuid, 'face-women-adult-acne-is-common', 'face', 'Ακμή στα 30 και στα 40: συχνή, και αντιμετωπίζεται', 'Acne in your 30s and 40s: common, and treatable', 'Πολλές γυναίκες βγάζουν σπυράκια για πρώτη φορά μετά τα 25 ή τα ξαναβρίσκουν τότε. Οι αιτίες είναι συνήθως ορμονικές διακυμάνσεις (περίοδος, εγκυμοσύνη, περιεμμηνόπαυση, έναρξη ή διακοπή αντισύλληψης), το άγχος, η κληρονομικότητα και προϊόντα που φράζουν τους πόρους. Αν τίποτα δεν βοηθά, ένας δερματολόγος συνήθως συνδυάζει δύο ή περισσότερες θεραπείες.', 'Many women get spots for the first time after 25, or see them return then. The usual causes are hormone shifts (periods, pregnancy, perimenopause, starting or stopping the pill), stress, family history and products that clog pores. If nothing helps, a dermatologist usually combines two or more treatments.', array['women']::text[], array['combination','oily','all']::text[], array['acne']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/acne/really-acne/adult-acne']::text[], false),
  ('5595e340-9efb-fb88-d355-6ed4fba259e5'::uuid, 'face-women-bakuchiol-not-tested-in-pregnancy', 'face', 'Μπακουχιόλη στην εγκυμοσύνη: «φυτικό» δεν σημαίνει ελεγμένο', 'Bakuchiol in pregnancy: “plant-based” does not mean tested', 'Η μπακουχιόλη προβάλλεται ως «η ρετινόλη της εγκυμοσύνης», αλλά οι μελέτες της είναι λίγες, μικρές και δεν αφορούν έγκυες. Δεν είναι ρετινοειδές, όμως ούτε έχει αποδειχτεί ασφαλής για το έμβρυο. Μέχρι να υπάρξουν στοιχεία, ρώτα τον γυναικολόγο σου ή κράτα το αζελαϊκό οξύ.', 'Bakuchiol is marketed as “the pregnancy retinol”, but its studies are few, small and do not include pregnant women. It is not a retinoid, yet it has not been shown to be safe for the baby either. Until there is evidence, ask your obstetrician or stick with azelaic acid.', array['women']::text[], array['all']::text[], array['aging','general']::text[], array['global']::text[], array['https://pubmed.ncbi.nlm.nih.gov/36176207/','https://www.aad.org/public/everyday-care/skin-care-secrets/routine/pregnancy-skin-care']::text[], false),
  ('7059f9df-23e7-098c-b66e-0f4250f8ce2f'::uuid, 'face-women-dark-spots-no-bleach-no-diy-peels', 'face', 'Κηλίδες: όχι χλωρίνη, όχι «σπιτικά» peeling', 'Dark spots: no bleach, no DIY peels', 'Η χλωρίνη και τα σπιτικά «λευκαντικά» βλάπτουν το δέρμα και δεν πρέπει ποτέ να μπαίνουν στο πρόσωπο. Σε πιο σκούρα επιδερμίδα, ακόμα και ένα δυνατό peeling ή μια συσκευή μικροδερμοαπόξεσης στο σπίτι μπορεί να αφήσει μόνιμες σκούρες κηλίδες. Πρώτα αντιμετωπίζεται η αιτία (ακμή, έκζεμα) και μετά, με τη βοήθεια δερματολόγου, οι κηλίδες.', 'Bleach and home-made “whitening” mixes harm the skin and must never go on the face. On darker skin, even a strong peel or an at-home microdermabrasion device can leave permanent dark marks. First the cause is treated (acne, eczema), then, with a dermatologist’s help, the spots.', array['women','all']::text[], array['all']::text[], array['pigmentation']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/routine/fade-dark-spots']::text[], false),
  ('cfe7f50e-7ebf-691c-318f-f70b2dba9d80'::uuid, 'face-women-mature-skin-one-retinoid-slowly', 'face', 'Ώριμο δέρμα: ένα ρετινοειδές, σιγά σιγά, πάνω σε καλή ενυδάτωση', 'Mature skin: one retinoid, slowly, over good moisture', 'Τα ρετινοειδή έχουν τα καλύτερα στοιχεία για λεπτές γραμμές και κηλίδες, αλλά ερεθίζουν πιο εύκολα το λεπτό, ξηρό δέρμα της εμμηνόπαυσης. Ξεκίνα με ρετινόλη ή ρετινάλη λίγα βράδια την εβδομάδα, πάνω ή κάτω από μια πλούσια κρέμα. Αν θέλεις ισχυρότερο ρετινοειδές με συνταγή, ρώτα δερματολόγο.', 'Retinoids have the best evidence for fine lines and dark spots, but they irritate the thin, dry skin of menopause more easily. Start with retinol or retinal a few nights a week, over or under a rich cream. If you want a stronger prescription retinoid, ask a dermatologist.', array['women']::text[], array['dry','normal']::text[], array['aging','texture']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/anti-aging/retinoid-retinol','https://www.aad.org/public/everyday-care/skin-care-secrets/anti-aging/skin-care-during-menopause']::text[], false),
  ('7c1f0d5a-7d2a-46e8-99ce-ab27856f8a86'::uuid, 'face-women-melasma-comes-back-without-sun-care', 'face', 'Το μέλασμα ξαναγυρίζει αν χαλαρώσει η αντηλιακή προστασία', 'Melasma returns when sun protection slips', 'Ακόμα και όταν ξεθωριάσει, το μέλασμα συχνά επιστρέφει με ένα καλοκαίρι χωρίς προστασία. Οι δερματολόγοι συστήνουν καθημερινά αντηλιακό SPF 30+ με οξείδιο του ψευδαργύρου, διοξείδιο του τιτανίου και οξείδια του σιδήρου, μαζί με καπέλο με φαρδύ γείσο και σκιά. Η ίδια προστασία χρειάζεται και τον χειμώνα, γιατί και το ορατό φως παίζει ρόλο.', 'Even once it has faded, melasma often comes back after one unprotected summer. Dermatologists recommend a daily SPF 30+ sunscreen with zinc oxide, titanium dioxide and iron oxides, plus a wide-brimmed hat and shade. The same protection is needed in winter, because visible light plays a part too.', array['women']::text[], array['all']::text[], array['pigmentation','sun']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/a-z/melasma-treatment','https://www.aad.org/public/diseases/a-z/melasma-self-care']::text[], false),
  ('5094d8c6-f505-8288-5f29-e791cd4d48fe'::uuid, 'face-women-melasma-tranexamic-acid', 'face', 'Τρανεξαμικό οξύ για το μέλασμα: τι δείχνουν οι μελέτες', 'Tranexamic acid for melasma: what the studies show', 'Ανασκοπήσεις κλινικών μελετών δείχνουν ότι το τρανεξαμικό οξύ, σε κρέμα ή ορό 2–5 %, μειώνει το μέλασμα μέσα σε 8–12 εβδομάδες, με ήπιες παρενέργειες. Λειτουργεί μόνο μαζί με καθημερινό αντηλιακό, και οι κηλίδες μπορεί να επιστρέψουν όταν το σταματήσεις. Το τρανεξαμικό σε χάπι είναι φάρμακο με συνταγή — αν είχες ποτέ θρόμβο, πες το στον δερματολόγο.', 'Reviews of clinical trials show that tranexamic acid, in a 2–5 % cream or serum, reduces melasma within 8–12 weeks with mild side effects. It works only alongside daily sunscreen, and the patches may come back when you stop. Tranexamic acid tablets are a prescription drug — if you have ever had a blood clot, tell the dermatologist.', array['women','all']::text[], array['all']::text[], array['pigmentation']::text[], array['global']::text[], array['https://pmc.ncbi.nlm.nih.gov/articles/PMC6247725/','https://pmc.ncbi.nlm.nih.gov/articles/PMC10718129/','https://www.aad.org/public/diseases/a-z/melasma-treatment']::text[], false),
  ('555a3018-8948-2753-368d-3209bc3969da'::uuid, 'face-women-one-anti-ageing-concern-at-a-time', 'face', 'Αντιγήρανση: ένας στόχος τη φορά, όχι πέντε προϊόντα', 'Anti-ageing: one goal at a time, not five products', 'Κανένα προϊόν δεν διορθώνει όλα τα σημάδια γήρανσης, και πολλά μαζί ερεθίζουν το δέρμα. Ξεκίνα από αντηλιακό και ενυδατική, και μετά διάλεξε έναν στόχο — γραμμές, κηλίδες ή χαλάρωση. Υποσχέσεις όπως «δέκα χρόνια νεότερη σε μια νύχτα» είναι πολύ καλές για να είναι αληθινές.', 'No single product fixes every sign of ageing, and using many at once irritates the skin. Start with sunscreen and moisturiser, then pick one goal — lines, spots or sagging. Promises such as “ten years younger overnight” are too good to be true.', array['women','all']::text[], array['all']::text[], array['aging']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/anti-aging/selecting-anti-aging-products']::text[], false),
  ('e46ee86f-c65f-bfe3-41d8-32c0e9c230f1'::uuid, 'face-women-perimenopause-skin-changes', 'face', 'Περιεμμηνόπαυση: το δέρμα αλλάζει πριν σταματήσει η περίοδος', 'Perimenopause: the skin changes before periods stop', 'Τα χρόνια πριν την εμμηνόπαυση, η πτώση των ορμονών μπορεί να φέρει ξηρό δέρμα, φαγούρα, σπυράκια ή πιο έντονες κηλίδες. Ήπιο καθαριστικό αντί για σαπούνι, ενυδατική αμέσως μετά το μπάνιο και αντηλιακό κάθε μέρα είναι η βάση. Για τα υπόλοιπα συμπτώματα της περιεμμηνόπαυσης μίλησε με τον γιατρό σου.', 'In the years before menopause, falling hormone levels can bring dry or itchy skin, breakouts or more noticeable dark spots. A mild cleanser instead of soap, moisturiser straight after bathing and daily sunscreen are the basis. For the other symptoms of perimenopause, talk to your doctor.', array['women']::text[], array['dry','all']::text[], array['aging','hydration']::text[], array['global']::text[], array['https://www.nhs.uk/conditions/menopause-and-perimenopause/symptoms/','https://www.aad.org/public/everyday-care/skin-care-secrets/anti-aging/skin-care-during-menopause']::text[], false),
  ('0177c1ef-2e5a-f534-e6c4-503a2452ac1e'::uuid, 'face-women-pregnancy-melasma-often-fades', 'face', 'Οι κηλίδες της εγκυμοσύνης συχνά ξεθωριάζουν μετά τον τοκετό', 'Pregnancy patches often fade after the birth', 'Οι ορμόνες της εγκυμοσύνης πυροδοτούν συχνά μέλασμα, που μπορεί να ξεθωριάσει μόνο του όταν τελειώσει η εγκυμοσύνη. Μέχρι τότε, σκιά, καπέλο και αντηλιακό με χρώμα κάθε μέρα, γιατί ο ήλιος το κάνει πιο σκούρο. Αν επιμένει μήνες μετά τον θηλασμό, ένας δερματολόγος έχει θεραπείες που δεν χρησιμοποιούνται στην εγκυμοσύνη.', 'Pregnancy hormones often trigger melasma, which can fade on its own once the pregnancy is over. Until then, shade, a hat and a tinted sunscreen every day, because sun makes it darker. If it lingers months after breastfeeding, a dermatologist has treatments that are not used in pregnancy.', array['women']::text[], array['all']::text[], array['pigmentation','sun']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/a-z/melasma-treatment','https://www.aad.org/public/everyday-care/skin-care-secrets/routine/pregnancy-skin-care']::text[], false),
  ('92f75735-9192-8669-6191-063842a0b340'::uuid, 'face-women-pregnancy-short-gentle-routine', 'face', 'Εγκυμοσύνη: μικρή, ήπια ρουτίνα και αντηλιακό με ορυκτά φίλτρα', 'Pregnancy: a short, gentle routine and a mineral sunscreen', 'Στην εγκυμοσύνη το δέρμα συχνά γίνεται πιο ευαίσθητο, οπότε λιγότερα προϊόντα χωρίς άρωμα είναι καλύτερη ιδέα. Αζελαϊκό οξύ και γλυκολικό οξύ είναι από τις επιλογές που προτείνουν οι δερματολόγοι, μαζί με αντηλιακό με οξείδιο του ψευδαργύρου ή διοξείδιο του τιτανίου. Ρετινοειδή, ρετινόλη και υδροκινόνη μένουν εκτός, και κάθε αγωγή τη συζητάς με τον γυναικολόγο σου.', 'In pregnancy the skin is often more sensitive, so fewer, fragrance-free products are a better idea. Azelaic acid and glycolic acid are among the options dermatologists suggest, with a zinc oxide or titanium dioxide sunscreen. Retinoids, retinol and hydroquinone stay out, and you discuss every treatment with your obstetrician.', array['women']::text[], array['all']::text[], array['acne','pigmentation','general']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-secrets/routine/pregnancy-skin-care','https://www.aad.org/public/diseases/acne/derm-treat/pregnancy']::text[], false),
  ('e9f5c4f5-bc7e-96a7-fb70-5db7c3dcea6f'::uuid, 'face-women-remove-eye-makeup-without-rubbing', 'face', 'Ντεμακιγιάζ ματιών: κράτα το βαμβάκι, μην τρίβεις', 'Eye make-up removal: hold the pad, do not rub', 'Το δέρμα των βλεφάρων είναι από τα πιο λεπτά του σώματος, και το τρίψιμο το ερεθίζει. Μούσκεψε ένα βαμβάκι με ντεμακιγιάζ, κράτα το λίγα δευτερόλεπτα πάνω στο μάτι και σκούπισε απαλά προς τα κάτω. Μετά πλύνε το πρόσωπο με ήπιο καθαριστικό και τα δάχτυλά σου, όχι με πανάκι.', 'Eyelid skin is among the thinnest on the body, and rubbing irritates it. Soak a pad with remover, hold it on the eye for a few seconds and wipe gently downwards. Then wash your face with a mild cleanser and your fingertips, not a washcloth.', array['women']::text[], array['all','sensitive']::text[], array['general']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/skin-care-basics/care/face-washing-101','https://www.aad.org/public/diseases/acne/causes/makeup']::text[], false),
  ('097a589d-2a06-b9d1-8775-b14e1f04e389'::uuid, 'face-women-spf-powder-and-primer-are-top-ups', 'face', 'Πούδρα και primer με SPF: συμπλήρωμα, όχι το κύριο αντηλιακό', 'SPF powder and primer: a top-up, not your main sunscreen', 'Το SPF της ετικέτας μετριέται με γενναία ποσότητα, πολύ περισσότερη από όση βάζουμε από μια πούδρα ή ένα primer. Βάλε πρώτα ένα κανονικό αντηλιακό σε όλο το πρόσωπο και κράτα την πούδρα για ανανέωση πάνω από το μακιγιάζ. Στην παραλία η ανανέωση γίνεται με αντηλιακό, κάθε δύο ώρες και μετά το κολύμπι.', 'The SPF on the label is measured with a generous layer, far more than anyone applies from a powder or a primer. Put a regular sunscreen over the whole face first and keep the powder for top-ups over make-up. At the beach, reapply real sunscreen every two hours and after swimming.', array['women']::text[], array['all']::text[], array['sun']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen','https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun']::text[], false),
  ('0cc0c83a-f30a-d00e-4cc5-8038f90aadef'::uuid, 'face-women-tinted-sunscreen-instead-of-foundation', 'face', 'Αντηλιακό με χρώμα αντί για make-up τις καθημερινές', 'Tinted sunscreen instead of foundation on weekdays', 'Ένα αντηλιακό με χρώμα και οξείδια του σιδήρου δίνει ελαφριά κάλυψη και προστατεύει και από το ορατό φως, κάτι που βοηθά όσες έχουν κηλίδες. Επειδή μπαίνει σε πλήρη ποσότητα, προστατεύει καλύτερα από ένα make-up με SPF. Ταιριάζει και σε όσες έχουν κοκκινίλες, γιατί το χρώμα τις καλύπτει.', 'A tinted sunscreen with iron oxides gives light coverage and also protects against visible light, which helps anyone with dark spots. Because it goes on in full amount, it protects better than a foundation with SPF. It also suits skin with redness, because the tint covers it.', array['women']::text[], array['all']::text[], array['sun','pigmentation','redness']::text[], array['global']::text[], array['https://www.aad.org/public/diseases/a-z/melasma-treatment','https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/choosing-right-sunscreen']::text[], false),
  ('fd2ddf03-8db7-fdec-8fc6-4fc7f2ebb89c'::uuid, 'nails-artificial-nails-for-special-occasions', 'nails', 'Τεχνητά νύχια για τις ειδικές περιστάσεις, όχι για όλο τον χρόνο', 'Artificial nails for special occasions, not all year round', 'Τα τεχνητά νύχια και το συνεχόμενο ημιμόνιμο δεν αφήνουν τα φυσικά νύχια να συνέλθουν. Οι δερματολόγοι προτείνουν να τα κρατάς για ειδικές περιστάσεις και, όταν τα βάζεις, να ζητάς gel που αφαιρείται με μούλιασμα, πιο ελαστικό από το ακρυλικό. Ζήτα επίσης να μην κόβονται τα επωνύχια, γιατί προστατεύουν από λοιμώξεις.', 'Artificial nails and back-to-back gel manicures leave natural nails no time to recover. Dermatologists suggest saving them for special occasions and, when you do wear them, asking for soak-off gel, which is more flexible than acrylic. Also ask that your cuticles are not trimmed, because they protect against infection.', array['women']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/nail-care-secrets/basics/pedicures/reduce-artificial-nail-damage']::text[], false),
  ('28af490e-41bc-3fea-d18e-107204d48425'::uuid, 'nails-biotin-is-not-a-quick-fix', 'nails', 'Βιοτίνη για τα νύχια: λίγα στοιχεία και μια παγίδα στις εξετάσεις', 'Biotin for nails: thin evidence and a blood-test trap', 'Οι μελέτες για τη βιοτίνη στα εύθραυστα νύχια είναι μικρές και χωρίς ομάδα ελέγχου, οπότε το όφελος δεν είναι αποδεδειγμένο. Οι υψηλές δόσεις μπορούν να αλλοιώσουν αποτελέσματα αιματολογικών εξετάσεων, όπως του θυρεοειδούς. Αν παίρνεις συμπλήρωμα βιοτίνης, πες το στον γιατρό πριν από κάθε εξέταση αίματος.', 'Studies of biotin for brittle nails are small and lack control groups, so the benefit is unproven. High doses can distort blood test results, thyroid tests among them. If you take a biotin supplement, tell your doctor before any blood test.', array['all','women']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://ods.od.nih.gov/factsheets/Biotin-HealthProfessional/','https://pmc.ncbi.nlm.nih.gov/articles/PMC6994568/']::text[], false),
  ('50fbbeee-3d57-4336-c423-ed9b3262e2b1'::uuid, 'nails-brittle-nails-moisturise-the-plate', 'nails', 'Εύθραυστα νύχια: ενυδάτωσε την πλάκα, όχι μόνο τα χέρια', 'Brittle nails: moisturise the plate, not just the hands', 'Τα νύχια που σχίζονται σε στρώσεις συχνά απλώς στεγνώνουν από το συνεχές βρέξιμο και στέγνωμα. Κρέμες με γλυκερίνη, ουρία, λανολίνη ή βαζελίνη, τριμμένες πάνω στο νύχι και γύρω του κάθε βράδυ, βοηθούν την πλάκα να κρατάει νερό. Κράτα τα νύχια κοντά, και αν σπάνε χωρίς λόγο ή αλλάζουν μορφή, δείξ’ τα σε γιατρό.', 'Nails that split into layers have often simply dried out from constant wetting and drying. Creams with glycerin, urea, lanolin or petrolatum, rubbed into and around the nail every night, help the plate hold water. Keep nails short, and if they break for no reason or change shape, show them to a doctor.', array['all','women']::text[], array['all']::text[], array['nails','hydration']::text[], array['global']::text[], array['https://pmc.ncbi.nlm.nih.gov/articles/PMC6994568/','https://www.aad.org/public/everyday-care/nail-care-secrets/basics/healthy-nail-tips']::text[], false),
  ('39e9084e-78c2-0bec-0be8-e3023683832c'::uuid, 'nails-changes-worth-showing-a-doctor', 'nails', 'Αλλαγές στα νύχια που αξίζει να δει γιατρός', 'Nail changes worth showing a doctor', 'Μια σκούρα γραμμή που εμφανίστηκε χωρίς χτύπημα, ένα νύχι που ξεκολλάει από το δέρμα, αλλαγές στο σχήμα ή στο χρώμα, ή πόνος και πρήξιμο γύρω από το νύχι θέλουν γιατρό. Οι περισσότερες αλλαγές στα νύχια είναι αθώες, αλλά κάποιες σχετίζονται με λοίμωξη ή άλλες παθήσεις. Μην τις καλύπτεις με βερνίκι μέχρι να τις δει κάποιος.', 'A dark streak that appeared without an injury, a nail lifting off the skin, changes in shape or colour, or pain and swelling around the nail need a doctor. Most nail changes are harmless, but some are linked to infection or other conditions. Do not cover them with polish until someone has looked.', array['all']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.nhs.uk/symptoms/nail-problems/']::text[], false),
  ('c56dad75-e6e8-8f6d-2cee-6a6ebf97bf66'::uuid, 'nails-cotton-under-vinyl-gloves-for-wet-work', 'nails', 'Για τις δουλειές με νερό: βαμβακερά γάντια μέσα σε γάντια βινυλίου', 'For wet work: cotton gloves under vinyl ones', 'Η ανασκόπηση για τα εύθραυστα νύχια προτείνει βαμβακερά γάντια κάτω από γάντια βινυλίου για πιάτα και καθαριότητα, και χοντρά βαμβακερά για τις ξερές δουλειές. Τα κλειστά γάντια πάνω σε βρεγμένα χέρια μπορεί να κάνουν τα νύχια να σχίζονται, γι’ αυτό στέγνωνε καλά τα χέρια πριν. Μετά, κρέμα χεριών μέχρι τα επωνύχια.', 'The review on brittle nails suggests cotton gloves under vinyl gloves for dishes and cleaning, and heavy cotton gloves for dry chores. Occlusive gloves over wet hands can make nails split, so dry your hands well first. Afterwards, hand cream right up to the cuticles.', array['all']::text[], array['all']::text[], array['nails','hands']::text[], array['global']::text[], array['https://pmc.ncbi.nlm.nih.gov/articles/PMC6994568/']::text[], false),
  ('f5047e1d-6c61-87e4-81cc-c4c2fbfa5912'::uuid, 'nails-gel-manicure-hand-sunscreen-or-gloves', 'nails', 'Ημιμόνιμο: αντηλιακό ή γάντια για τα χέρια κάτω από τη λάμπα', 'Gel manicure: sunscreen or gloves for your hands under the lamp', 'Οι λάμπες που «ψήνουν» το ημιμόνιμο εκπέμπουν υπεριώδη ακτινοβολία, και τα επαναλαμβανόμενα μανικιούρ αυξάνουν τη γήρανση και τον κίνδυνο καρκίνου του δέρματος στα χέρια. Βάλε αντηλιακό SPF 30+ ανθεκτικό στο νερό στα χέρια πριν, ή φόρα σκούρα γάντια με κομμένες άκρες.', 'The lamps that cure gel polish give off UV light, and repeated manicures increase skin ageing and skin cancer risk on the hands. Put water-resistant SPF 30+ on your hands beforehand, or wear dark gloves with the fingertips cut off.', array['women','all']::text[], array['all']::text[], array['nails','hands']::text[], array['global']::text[], array['https://www.aad.org/media/news-releases/gel-manicures-dermatologists-share-tips-to-keep-nails-healthy','https://www.aad.org/public/everyday-care/nail-care-secrets/basics/pedicures/reduce-artificial-nail-damage']::text[], false),
  ('444b63b0-8e4a-520d-b90f-b9ed4d1df1f6'::uuid, 'nails-gel-soak-off-never-peel', 'nails', 'Το ημιμόνιμο μουλιάζει και φεύγει — δεν ξεκολλιέται', 'Gel polish is soaked off — never peeled off', 'Όταν τραβάς ή ξύνεις το ημιμόνιμο που σηκώνεται, παίρνεις μαζί στρώσεις από την πλάκα του νυχιού. Ζήτα στο σαλόνι αφαίρεση με μούλιασμα σε ασετόνη και μην «πειράζεις» το βερνίκι που ξεφλουδίζει. Αν είσαι αλλεργική στην ασετόνη ή έχεις συχνά προβλήματα στα νύχια, προτίμησε κλασικό βερνίκι.', 'When you pull or pick at lifting gel polish, layers of the nail plate come off with it. Ask the salon for acetone soak-off removal and do not pick at chipping polish. If you are allergic to acetone or often have nail problems, choose regular polish instead.', array['women']::text[], array['all']::text[], array['nails']::text[], array['global']::text[], array['https://www.aad.org/media/news-releases/gel-manicures-dermatologists-share-tips-to-keep-nails-healthy','https://www.aad.org/public/everyday-care/nail-care-secrets/basics/pedicures/reduce-artificial-nail-damage']::text[], false),
  ('ed41f27d-b045-0cd8-f654-ae90f432e6ca'::uuid, 'nails-hands-show-age-sunscreen-on-the-backs', 'nails', 'Τα χέρια δείχνουν την ηλικία: αντηλιακό και στη ράχη τους', 'Hands show age: sunscreen on the backs too', 'Η ράχη των χεριών παίρνει ήλιο κάθε μέρα, στο τιμόνι, στο κινητό και στη βόλτα, και εκεί εμφανίζονται νωρίς οι κηλίδες. Βάλε αντηλιακό ή κρέμα χεριών με SPF το πρωί και ανανέωσέ τη μετά από κάθε πλύσιμο. Το ελληνικό καλοκαίρι, πάρε ένα μικρό σωληνάριο στην τσάντα.', 'The backs of the hands catch sun every day, at the wheel, on the phone and out walking, and that is where spots appear early. Put on sunscreen or a hand cream with SPF in the morning and reapply after every wash. In a Greek summer, keep a small tube in your bag.', array['women','all']::text[], array['all']::text[], array['hands','sun','nails']::text[], array['global']::text[], array['https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen','https://www.aad.org/media/news-releases/gel-manicures-dermatologists-share-tips-to-keep-nails-healthy']::text[], false)
